screenPanels.initJs:
function(container, apiUrl, tables) {
  // ========================================
  // 1. OCR画像をCanvasに描画（サンプル）
  // ========================================
  const canvas = container.querySelector("#ocr-canvas");
  const ctx = canvas.getContext("2d");

  // キャンバスをクリア
  ctx.fillStyle = "#1a2a40";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // サンプルOCR画像を描画（テキストベース）
  ctx.fillStyle = "#d0e4ff";
  ctx.font = "14px sans-serif";
  ctx.fillText("【受注書】", 20, 40);
  ctx.font = "12px sans-serif";
  ctx.fillText("顧客名: 株式会社サンプル", 20, 70);
  ctx.fillText("受注日: 2025-01-15", 20, 95);
  ctx.fillText("受注金額: ¥150,000", 20, 120);
  ctx.fillText("商品コード: SKU-001", 20, 145);
  ctx.fillText("数量: 5 個", 20, 170);
  ctx.fillText("配送先: 東京都渋谷区", 20, 195);

  // ========================================
  // 2. 初期データ表示（サンプルデータ）
  // ========================================
  const ocrData = {
    customer_name: "株式会社サンプル",
    order_date: "2025-01-15",
    order_amount: "150000",
    product_info: "SKU-001",
    confidence_score: 85,
    customer_confidence: 92,
    product_confidence: 78,
    amount_confidence: 88,
    shipping_confidence: 75
  };

  // 信頼度スコアを表示
  container.querySelector("#overall-confidence").textContent = ocrData.confidence_score;
  container.querySelector("#conf-customer").textContent = ocrData.customer_confidence + "%";
  container.querySelector("#conf-product").textContent = ocrData.product_confidence + "%";
  container.querySelector("#conf-amount").textContent = ocrData.amount_confidence + "%";
  container.querySelector("#conf-shipping").textContent = ocrData.shipping_confidence + "%";

  // フォーム入力欄に初期値を設定
  container.querySelector("[data-testid='customer-name-input']").value = ocrData.customer_name;
  container.querySelector("[data-testid='order-amount-input']").value = ocrData.order_amount;
  container.querySelector("[data-testid='product-code-input']").value = ocrData.product_info;

  // ========================================
  // 3. ボタンイベント: 重複受注確認
  // ========================================
  container.querySelector("[data-testid='view-duplicate-btn']").addEventListener("click", () => {
    window.showScreen("scr-1781406366334");
  });

  // ========================================
  // 4. ボタンイベント: チャネル間矛盾確認
  // ========================================
  container.querySelector("[data-testid='view-discrepancy-btn']").addEventListener("click", () => {
    window.showScreen("scr-1781406379487");
  });

  // ========================================
  // 5. ボタンイベント: 過去受注履歴参照
  // ========================================
  container.querySelector("[data-testid='view-history-btn']").addEventListener("click", () => {
    window.showScreen("scr-1781406434707");
  });

  // ========================================
  // 6. ボタンイベント: キャンセル
  // ========================================
  container.querySelector("[data-testid='cancel-button']").addEventListener("click", () => {
    window.showScreen("scr-1781406322572");
  });

  // ========================================
  // 7. ボタンイベント: 修正を保存
  // ========================================
  container.querySelector("[data-testid='save-correction-button']").addEventListener("click", async () => {
    const confirmCheckbox = container.querySelector("[data-testid='confirm-correction-checkbox']");
    if (!confirmCheckbox.checked) {
      alert("修正内容を確認してください");
      return;
    }

    const correctionData = {
      customer_name: container.querySelector("[data-testid='customer-name-input']").value,
      order_amount: container.querySelector("[data-testid='order-amount-input']").value,
      product_code: container.querySelector("[data-testid='product-code-input']").value,
      correction_reason: container.querySelector("[data-testid='correction-reason-input']").value,
      corrected_at: new Date().toISOString(),
      corrected_by: "current_user"
    };

    // API経由で修正履歴を保存（テーブルインデックス 1 = 受注データ修正履歴）
    if (tables.length > 1) {
      const saved = await window.aivicApi.save(1, correctionData);
      if (saved) {
        alert("修正を保存しました");
        // 修正履歴を再描画
        const timeline = container.querySelector("#correction-timeline");
        const newEntry = document.createElement("div");
        newEntry.style.cssText = "display: flex; gap: 8px;";
        newEntry.innerHTML = `
          <div style="width: 3px; background: #4ade80; border-radius: 2px; flex-shrink: 0;"></div>
          <div style="font-size: 11px;">
            <div style="color: var(--text); font-weight: 600;">修正保存</div>
            <div style="color: var(--text-muted); font-size: 10px;">${new Date().toLocaleString('ja-JP')}</div>
            <div style="color: var(--text); margin-top: 2px;">修正内容が保存されました</div>
          </div>
        `;
        timeline.insertBefore(newEntry, timeline.firstChild);
      }
    }
  });

  // ========================================
  // 8. ボタンイベント: 承認フローへ進む
  // ========================================
  container.querySelector("[data-testid='submit-approval-button']").addEventListener("click", () => {
    const confirmCheckbox = container.querySelector("[data-testid='confirm-correction-checkbox']");
    if (!confirmCheckbox.checked) {
      alert("修正内容を確認してください");
      return;
    }
    window.showScreen("scr-1781406421345");
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 重複受注検出テーブルは tables[0] と仮定
  const tableIndex = 0;
  let allRows = [];
  let selectedRow = null;

  // 1. 再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#duplicate-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: var(--bg-main); color: var(--text-muted);"><td colspan="8" style="padding: 1rem; text-align: center;">該当データなし</td></tr>';
      return;
    }
    tbody.innerHTML = rows.map(r => {
      const scoreClass = r.重複スコア >= 90 ? 'high' : r.重複スコア >= 70 ? 'medium' : 'low';
      const statusBg = r.重複ステータス === '確認済み' ? '#4a7c59' : r.重複ステータス === '統合済み' ? '#2a5a3a' : '#5a5a3a';
      return `
        <tr data-id="${r.重複受注検出ID}" style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background='transparent'">
          <td style="padding: 0.5rem; border-right: 1px solid var(--border); color: var(--primary);">${r.主受注ID ? r.主受注ID.substring(0, 8) : '-'}</td>
          <td style="padding: 0.5rem; border-right: 1px solid var(--border); color: var(--primary);">${r.副受注ID ? r.副受注ID.substring(0, 8) : '-'}</td>
          <td style="padding: 0.5rem; border-right: 1px solid var(--border);">${r.顧客名 || '-'}</td>
          <td style="padding: 0.5rem; border-right: 1px solid var(--border); text-align: center; font-weight: 600; color: ${scoreClass === 'high' ? '#ff9a56' : scoreClass === 'medium' ? '#ffc857' : '#9fb0d1'};">${r.重複スコア || 0}%</td>
          <td style="padding: 0.5rem; border-right: 1px solid var(--border); text-align: center;">${r.信頼度スコア || '-'}%</td>
          <td style="padding: 0.5rem; border-right: 1px solid var(--border); text-align: center; font-size: 0.75rem;">${r.チャネル || '-'}</td>
          <td style="padding: 0.5rem; border-right: 1px solid var(--border); text-align: center;">
            <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 0.25rem; background: ${statusBg}; color: #fff; font-size: 0.75rem;">${r.重複ステータス || '未確認'}</span>
          </td>
          <td style="padding: 0.5rem; text-align: center;">
            <button class="action-btn secondary compare-btn" data-id="${r.重複受注検出ID}" style="padding: 0.25rem 0.5rem; font-size: 0.75rem;">比較</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データ読み込み
  allRows = tables[tableIndex]?.records || [];
  renderRows(allRows);

  // 3. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const orderId = container.querySelector("#filter-order-id").value.toLowerCase();
    const customer = container.querySelector("#filter-customer").value.toLowerCase();
    const channel = container.querySelector("#filter-channel").value;
    const scoreRange = container.querySelector("#filter-duplicate-score").value;

    let filtered = allRows.filter(r => {
      const matchOrder = !orderId || (r.主受注ID || '').toLowerCase().includes(orderId) || (r.副受注ID || '').toLowerCase().includes(orderId);
      const matchCustomer = !customer || (r.顧客名 || '').toLowerCase().includes(customer);
      const matchChannel = !channel || r.チャネル === channel;
      let matchScore = true;
      if (scoreRange === '90-100') matchScore = (r.重複スコア || 0) >= 90;
      else if (scoreRange === '70-89') matchScore = (r.重複スコア || 0) >= 70 && (r.重複スコア || 0) < 90;
      else if (scoreRange === '0-69') matchScore = (r.重複スコア || 0) < 70;
      return matchOrder && matchCustomer && matchChannel && matchScore;
    });
    renderRows(filtered);
  });

  // 4. 比較ボタン（行レベル）
  container.addEventListener("click", async e => {
    const compareBtn = e.target.closest(".compare-btn");
    if (compareBtn) {
      const rowId = compareBtn.dataset.id;
      selectedRow = allRows.find(r => r.重複受注検出ID === rowId);
      if (selectedRow) {
        // 主受注データ詳細表示
        const primaryDetail = `
          <div style="margin-bottom: 0.5rem;">
            <strong>受注ID:</strong> ${selectedRow.主受注ID ? selectedRow.主受注ID.substring(0, 12) : '-'}<br/>
            <strong>顧客名:</strong> ${selectedRow.顧客名 || '-'}<br/>
            <strong>受注日:</strong> ${selectedRow.受注日 || '-'}<br/>
            <strong>金額:</strong> ${selectedRow.金額 ? '¥' + selectedRow.金額.toLocaleString() : '-'}<br/>
            <strong>チャネル:</strong> ${selectedRow.チャネル || '-'}<br/>
            <strong>信頼度:</strong> ${selectedRow.信頼度スコア || '-'}%
          </div>
        `;
        container.querySelector("#detail-primary").innerHTML = primaryDetail;

        // 副受注データ詳細表示（差分ハイライト）
        const secondaryDetail = `
          <div style="margin-bottom: 0.5rem;">
            <strong>受注ID:</strong> <span style="background: rgba(255,165,0,0.3);">${selectedRow.副受注ID ? selectedRow.副受注ID.substring(0, 12) : '-'}</span><br/>
            <strong>顧客名:</strong> <span style="background: rgba(255,165,0,0.3);">${selectedRow.顧客名_副 || selectedRow.顧客名 || '-'}</span><br/>
            <strong>受注日:</strong> <span style="background: rgba(255,165,0,0.3);">${selectedRow.受注日_副 || selectedRow.受注日 || '-'}</span><br/>
            <strong>金額:</strong> <span style="background: rgba(255,165,0,0.3);">${selectedRow.金額_副 ? '¥' + selectedRow.金額_副.toLocaleString() : '-'}</span><br/>
            <strong>チャネル:</strong> <span style="background: rgba(255,165,0,0.3);">${selectedRow.チャネル_副 || selectedRow.チャネル || '-'}</span><br/>
            <strong>信頼度:</strong> <span style="background: rgba(255,165,0,0.3);">${selectedRow.信頼度スコア_副 || selectedRow.信頼度スコア || '-'}%</span>
          </div>
        `;
        container.querySelector("#detail-secondary").innerHTML = secondaryDetail;

        // チャネル間矛盾検出結果
        const conflicts = selectedRow.矛盾検出結果 || [];
        const conflictHtml = conflicts.length > 0
          ? conflicts.map(c => `
              <div style="margin-bottom: 0.5rem; padding: 0.375rem; background: rgba(255,165,0,0.1); border-left: 3px solid #ff9a56; border-radius: 0.25rem;">
                <strong>${c.項目}:</strong> ${c.チャネル1値} → ${c.チャネル2値}<br/>
                <span style="font-size: 0.75rem; color: var(--text-muted);">重要度: ${c.重要度}</span>
              </div>
            `).join("")
          : '<div style="color: var(--text-muted);">矛盾なし</div>';
        container.querySelector("#channel-conflicts").innerHTML = conflictHtml;
      }
    }
  });

  // 5. 統合ボタン
  container.querySelector("#btn-merge").addEventListener("click", async () => {
    if (!selectedRow) {
      alert("比較対象を選択してください");
      return;
    }
    if (!confirm(`受注 ${selectedRow.主受注ID?.substring(0, 8)} と ${selectedRow.副受注ID?.substring(0, 8)} を統合しますか？`)) return;

    const updated = await window.aivicApi.update(tableIndex, selectedRow.重複受注検出ID, {
      重複ステータス: "統合済み",
      解決方法: "統合"
    });
    if (updated) {
      allRows = allRows.map(r => r.重複受注検出ID === selectedRow.重複受注検出ID ? { ...r, 重複ステータス: "統合済み" } : r);
      renderRows(allRows);
      selectedRow = null;
      container.querySelector("#detail-primary").innerHTML = '<div style="color: var(--text-muted);">選択してください</div>';
      container.querySelector("#detail-secondary").innerHTML = '<div style="color: var(--text-muted);">選択してください</div>';
    }
  });

  // 6. 分離ボタン
  container.querySelector("#btn-separate").addEventListener("click", async () => {
    if (!selectedRow) {
      alert("比較対象を選択してください");
      return;
    }
    if (!confirm("この重複を分離しますか？")) return;

    const updated = await window.aivicApi.update(tableIndex, selectedRow.重複受注検出ID, {
      重複ステータス: "分離済み",
      解決方法: "分離"
    });
    if (updated) {
      allRows = allRows.map(r => r.重複受注検出ID === selectedRow.重複受注検出ID ? { ...r, 重複ステータス: "分離済み" } : r);
      renderRows(allRows);
      selectedRow = null;
    }
  });

  // 7. 誤検出ボタン
  container.querySelector("#btn-dismiss").addEventListener("click", async () => {
    if (!selectedRow) {
      alert("比較対象を選択してください");
      return;
    }
    if (!confirm("この重複を誤検出として処理しますか？")) return;

    const updated = await window.aivicApi.update(tableIndex, selectedRow.重複受注検出ID, {
      重複ステータス: "誤検出",
      解決方法: "その他"
    });
    if (updated) {
      allRows = allRows.map(r => r.重複受注検出ID === selectedRow.重複受注検出ID ? { ...r, 重複ステータス: "誤検出" } : r);
      renderRows(allRows);
      selectedRow = null;
    }
  });

  // 8. 詳細確認ボタン
  container.querySelector("#btn-detail").addEventListener("click", () => {
    if (!selectedRow) {
      alert("比較対象を選択してください");
      return;
    }
    // 詳細確認画面へ遷移
    window.showScreen("scr-1781406337850");
  });

  // 9. CSVエクスポート
  container.querySelector("#btn-export").addEventListener("click", async () => {
    const rows = allRows;
    if (rows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }
    const headers = ["主受注ID", "副受注ID", "顧客名", "重複スコア", "信頼度スコア", "チャネル", "重複ステータス", "検出理由"];
    const csv = [
      '\uFEFF' + headers.join(","),
      ...rows.map(r => [
        r.主受注ID || "",
        r.副受注ID || "",
        r.顧客名 || "",
        r.重複スコア || "",
        r.信頼度スコア || "",
        r.チャネル || "",
        r.重複ステータス || "",
        r.重複検出理由 || ""
      ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "duplicate_orders_" + new Date().toISOString().split("T")[0] + ".csv";
    link.click();
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#record-tbody");
  const priorityFilter = container.querySelector("[data-testid='priority-filter']");
  const statusFilter = container.querySelector("[data-testid='status-filter']");
  const confidenceFilter = container.querySelector("[data-testid='confidence-filter']");
  const searchBtn = container.querySelector("[data-testid='search-button']");
  const exportBtn = container.querySelector("[data-testid='export-button']");
  const totalCount = container.querySelector("[data-testid='total-count']");
  const pendingCount = container.querySelector("[data-testid='pending-count']");
  const inProgressCount = container.querySelector("[data-testid='in-progress-count']");
  const completedCount = container.querySelector("[data-testid='completed-count']");

  // 優先度ランク定義
  const priorityRanks = {
    1: { name: "緊急", color: "#ff4444", bgColor: "rgba(255,68,68,0.15)" },
    2: { name: "高", color: "#ff6a00", bgColor: "rgba(255,106,0,0.15)" },
    3: { name: "中", color: "#ffc107", bgColor: "rgba(255,193,7,0.15)" },
    4: { name: "低", color: "#9fb0d1", bgColor: "rgba(159,176,209,0.15)" }
  };

  // ステータス色定義
  const statusColors = {
    "未対応": { color: "#ff6a00", bgColor: "rgba(255,106,0,0.15)" },
    "対応中": { color: "#ffc107", bgColor: "rgba(255,193,7,0.15)" },
    "対応完了": { color: "#4caf50", bgColor: "rgba(76,175,80,0.15)" }
  };

  // 再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const priority = r.優先度ランクID ? (priorityRanks[r.優先度ランクID] || priorityRanks[4]) : priorityRanks[4];
      const status = r.対応状況 || "未対応";
      const statusStyle = statusColors[status] || statusColors["未対応"];
      const confidence = r.信頼度スコア || 0;
      const confidenceColor = confidence >= 70 ? "#4caf50" : confidence >= 40 ? "#ffc107" : "#ff6a00";

      // 警告フラグ
      const hasWarning = (r.重複フラグ === true || r.重複フラグ === "true") || 
                         (r.チャネル間矛盾フラグ === true || r.チャネル間矛盾フラグ === "true");

      return `<tr data-id="${r.検証結果ID || r.id}" style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.04)'" onmouseout="this.style.background='transparent'">
        <td style="padding: 8px 12px;">
          <div style="display: inline-block; padding: 4px 8px; border-radius: 3px; background: ${priority.bgColor}; color: ${priority.color}; font-weight: 600; font-size: 11px;">
            ${priority.name}
          </div>
        </td>
        <td style="padding: 8px 12px; color: var(--text); font-family: monospace; font-size: 11px;">
          ${(r.受注ID || r.id || "").substring(0, 8)}
        </td>
        <td style="padding: 8px 12px; color: var(--text);">
          ${r.チャネル名 || "-"}
        </td>
        <td style="padding: 8px 12px; color: var(--text); max-width: 200px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">
          ${r.エラー詳細 || r.対象フィールド || "-"}
        </td>
        <td style="padding: 8px 12px; text-align: center;">
          <div style="display: flex; align-items: center; justify-content: center; gap: 4px;">
            <div style="width: 40px; height: 4px; background: rgba(255,255,255,0.1); border-radius: 2px; overflow: hidden;">
              <div style="width: ${confidence}%; height: 100%; background: ${confidenceColor}; transition: width 0.3s;"></div>
            </div>
            <span style="color: var(--text); font-weight: 600; font-size: 11px; min-width: 25px;">${confidence}%</span>
          </div>
        </td>
        <td style="padding: 8px 12px; color: var(--text-muted); font-size: 11px;">
          ${r.検証実行日時 ? new Date(r.検証実行日時).toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : "-"}
        </td>
        <td style="padding: 8px 12px; text-align: center;">
          <div style="display: inline-block; padding: 4px 8px; border-radius: 3px; background: ${statusStyle.bgColor}; color: ${statusStyle.color}; font-weight: 600; font-size: 11px;">
            ${status}
          </div>
        </td>
        <td style="padding: 8px 12px; color: var(--text);">
          ${r.対応者 || "-"}
        </td>
        <td style="padding: 8px 12px; color: var(--text-muted); font-size: 11px;">
          ${r.期限日 ? new Date(r.期限日).toLocaleDateString('ja-JP') : "-"}
        </td>
        <td style="padding: 8px 12px; text-align: center;">
          ${hasWarning ? '<span style="color: #ff6a00; font-weight: 600; font-size: 14px;">⚠</span>' : '-'}
        </td>
        <td style="padding: 8px 12px; text-align: center;">
          <button class="action-btn secondary detail-btn" data-id="${r.検証結果ID || r.id}" style="padding: 4px 8px; font-size: 11px;">詳細</button>
        </td>
      </tr>`;
    }).join("");
    updateStats(rows);
  }

  // 統計更新
  function updateStats(rows) {
    totalCount.textContent = rows.length;
    pendingCount.textContent = rows.filter(r => r.対応状況 === "未対応").length;
    inProgressCount.textContent = rows.filter(r => r.対応状況 === "対応中").length;
    completedCount.textContent = rows.filter(r => r.対応状況 === "対応完了").length;
  }

  // 初期データ表示
  const initialRows = tables[0]?.records || [];
  renderRows(initialRows);

  // 検索ボタン
  searchBtn.addEventListener("click", async () => {
    const priority = priorityFilter.value;
    const status = statusFilter.value;
    const confidence = confidenceFilter.value;

    let rows = await window.aivicApi.list(0) || initialRows;

    if (priority) {
      rows = rows.filter(r => String(r.優先度ランクID) === priority);
    }
    if (status) {
      rows = rows.filter(r => r.対応状況 === status);
    }
    if (confidence) {
      const [min, max] = confidence.split("-").map(Number);
      rows = rows.filter(r => {
        const conf = r.信頼度スコア || 0;
        return conf >= min && conf <= max;
      });
    }

    renderRows(rows);
  });

  // CSVエクスポート
  exportBtn.addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0) || initialRows;
    const headers = ["優先度", "受注ID", "チャネル", "エラー内容", "信頼度スコア", "検出日時", "修正ステータス", "担当者", "期限日", "重複フラグ", "矛盾フラグ"];
    const csv = [
      "\uFEFF" + headers.map(h => `"${h}"`).join(","),
      ...rows.map(r => {
        const priority = priorityRanks[r.優先度ランクID || 4]?.name || "-";
        return [
          `"${priority}"`,
          `"${(r.受注ID || r.id || "").substring(0, 8)}"`,
          `"${r.チャネル名 || ""}"`,
          `"${(r.エラー詳細 || "").replace(/"/g, '""')}"`,
          r.信頼度スコア || 0,
          `"${r.検証実行日時 || ""}"`,
          `"${r.対応状況 || ""}"`,
          `"${r.対応者 || ""}"`,
          `"${r.期限日 || ""}"`,
          r.重複フラグ ? "○" : "",
          r.チャネル間矛盾フラグ ? "○" : ""
        ].join(",");
      })
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `修正対象優先度一覧_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 詳細ボタン
  container.addEventListener("click", (e) => {
