function(container, apiUrl, tables) {
  // テーブルインデックスの確認
  const validationResultsIndex = 0;  // 受注データ検証結果
  const correctionHistoryIndex = 1;  // 受注データ修正履歴
  const trustScoreIndex = 2;         // 信頼度スコア
  const ocrResultIndex = 3;          // AI_OCR読込結果
  const duplicateIndex = 4;          // 重複受注検出
  const channelMismatchIndex = 5;    // チャネル間矛盾検出
  const approvalFlowIndex = 6;       // 連携承認フロー

  // サンプル受注ID（実際にはURLパラメータから取得）
  let currentOrderId = null;
  let currentValidationResult = null;
  let currentCorrectionHistory = [];

  // 初期データ読み込み
  async function loadOrderData() {
    // URL パラメータから受注ID取得（なければサンプル）
    const params = new URLSearchParams(window.location.search);
    currentOrderId = params.get('orderId') || (tables[validationResultsIndex]?.records?.[0]?.受注ID || 'ORD-2024-001');

    // 検証結果を取得
    const validationResults = await window.aivicApi.list(validationResultsIndex);
    currentValidationResult = validationResults?.find(r => r.受注ID === currentOrderId) || validationResults?.[0];

    // 修正履歴を取得
    const correctionHistories = await window.aivicApi.list(correctionHistoryIndex);
    currentCorrectionHistory = correctionHistories?.filter(h => h.受注データID === currentOrderId) || [];

    // UI更新
    renderOrderHeader();
    renderValidationSummary();
    renderCorrectionTimeline();
  }

  // ヘッダー情報の描画
  function renderOrderHeader() {
    if (!currentValidationResult) return;

    container.querySelector('#order-id-display').textContent = currentOrderId || '-';
    container.querySelector('#order-status-display').textContent = currentValidationResult.対応状況 || '未対応';

    const statusEl = container.querySelector('#order-status-display');
    if (currentValidationResult.対応状況 === '対応完了') {
      statusEl.style.background = '#4caf50';
    } else if (currentValidationResult.対応状況 === '対応中') {
      statusEl.style.background = '#ff9800';
    } else {
      statusEl.style.background = 'var(--primary)';
    }

    container.querySelector('#last-updated').textContent = 
      currentValidationResult.更新日時 ? new Date(currentValidationResult.更新日時).toLocaleString('ja-JP') : '-';
  }

  // 検証結果サマリーの描画
  function renderValidationSummary() {
    if (!currentValidationResult) return;

    // 信頼度スコア取得（サンプル）
    const trustScores = tables[trustScoreIndex]?.records || [];
    const trustScore = trustScores.find(t => t.受注データID === currentOrderId);
    const overallScore = trustScore?.全体信頼度スコア || 75;
    const riskLevel = trustScore?.リスク判定レベル || '中';

    container.querySelector('#score-overall').textContent = overallScore + '%';
    container.querySelector('#risk-level').textContent = riskLevel;

    // 検証結果詳細
    container.querySelector('#val-status').textContent = currentValidationResult.検証ステータス || '不合格';
    container.querySelector('#val-error-class').textContent = currentValidationResult.エラー分類 || '必須項目不足';
    container.querySelector('#val-severity').textContent = currentValidationResult.重要度 || '高';

    // 修正前後の差分表示
    container.querySelector('#diff-before').textContent = currentValidationResult.検出値 || '-';
    container.querySelector('#diff-expected').textContent = currentValidationResult.期待値 || '-';

    // 警告パネル表示判定
    const warningsPanel = container.querySelector('#warnings-panel');
    const duplicates = tables[duplicateIndex]?.records?.filter(d => d.主受注ID === currentOrderId || d.副受注ID === currentOrderId) || [];
    const mismatches = tables[channelMismatchIndex]?.records?.filter(m => m.受注ID === currentOrderId) || [];

    if (duplicates.length > 0 || mismatches.length > 0) {
      warningsPanel.style.display = 'block';
      let warningHtml = '';
      duplicates.forEach(d => {
        warningHtml += `<div style="margin-bottom: 4px;">🔄 重複受注検出: スコア ${d.重複スコア}%</div>`;
      });
      mismatches.forEach(m => {
        warningHtml += `<div style="margin-bottom: 4px;">⚠️ チャネル間矛盾: ${m.矛盾項目}</div>`;
      });
      container.querySelector('#warnings-list').innerHTML = warningHtml;
    } else {
      warningsPanel.style.display = 'none';
    }
  }

  // 修正履歴タイムラインの描画
  function renderCorrectionTimeline() {
    const timeline = container.querySelector('#correction-timeline');

    if (currentCorrectionHistory.length === 0) {
      timeline.innerHTML = '<div style="padding: 8px; text-align: center; color: var(--text-muted);">修正履歴がありません</div>';
      return;
    }

    const html = currentCorrectionHistory
      .sort((a, b) => new Date(b.修正日時) - new Date(a.修正日時))
      .map(h => `
        <div style="padding: 10px; border-left: 2px solid var(--primary); margin-bottom: 8px; background: rgba(0,0,0,0.04); border-radius: 2px;">
          <div style="font-weight: 600; color: var(--text); margin-bottom: 3px;">
            ${h.修正フィールド名}
          </div>
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 4px;">
            ${new Date(h.修正日時).toLocaleString('ja-JP')} by ${h.修正者名 || h.修正者ID}
          </div>
          <div style="font-size: 11px; color: var(--text); margin-bottom: 3px;">
            <span style="color: var(--text-muted);">修正前:</span> <span style="font-family: monospace;">${h.修正前の値 || '-'}</span>
          </div>
          <div style="font-size: 11px; color: var(--text); margin-bottom: 4px;">
            <span style="color: var(--text-muted);">修正後:</span> <span style="font-family: monospace;">${h.修正後の値 || '-'}</span>
          </div>
          <div style="font-size: 11px; color: var(--text); padding: 6px; background: rgba(0,0,0,0.08); border-radius: 2px;">
            ${h.修正理由 || '理由なし'}
          </div>
        </div>
      `).join('');

    timeline.innerHTML = html;
  }

  // 修正を保存
  async function saveCorrection() {
    const fieldSelect = container.querySelector('#field-select');
    const correctionValue = container.querySelector('#correction-value');
    const correctionReason = container.querySelector('#correction-reason');
    const prioritySelect = container.querySelector('#priority-select');

    if (!fieldSelect.value || !correctionValue.value || !correctionReason.value) {
      alert('すべての項目を入力してください');
      return;
    }

    const correctionRecord = {
      受注データID: currentOrderId,
      修正フィールド名: fieldSelect.value,
      修正前の値: currentValidationResult?.検出値 || '',
      修正後の値: correctionValue.value,
      修正理由: correctionReason.value,
      修正者ID: 'USER-001',
      修正者名: 'システムユーザー',
      修正日時: new Date().toISOString(),
      検証結果ID: currentValidationResult?.検証結果ID || null
    };

    const saved = await window.aivicApi.save(correctionHistoryIndex, correctionRecord);

    if (saved) {
      alert('修正を保存しました');
      // フォームクリア
      fieldSelect.value = '';
      correctionValue.value = '';
      correctionReason.value = '';
      prioritySelect.value = '';

      // 履歴再読み込み
      await loadOrderData();
    }
  }

  // イベントリスナー登録
  container.querySelector('#btn-save-correction').addEventListener('click', saveCorrection);

  container.querySelector('#btn-cancel-correction').addEventListener('click', () => {
    container.querySelector('#field-select').value = '';
    container.querySelector('#correction-value').value = '';
    container.querySelector('#correction-reason').value = '';
    container.querySelector('#priority-select').value = '';
  });

  container.querySelector('#btn-back-to-dashboard').addEventListener('click', () => {
    window.showScreen('scr-1781406322572');
  });

  container.querySelector('#btn-submit-approval').addEventListener('click', () => {
    if (currentCorrectionHistory.length === 0) {
      alert('修正履歴がありません。修正を保存してから承認へ進んでください');
      return;
    }
    window.showScreen('scr-1781406421345');
  });

  // 初期化実行
  loadOrderData();
}

