        <td style="color: #4ade80;">${r.修正後の値 || ""}</td>
        <td>${r.修正者名 || r.修正者ID || ""}</td>
        <td>${r.修正日時 ? new Date(r.修正日時).toLocaleString('ja-JP') : ""}</td>
      </tr>
    `).join("");
  }

  // 2. 初期データ読み込み（修正履歴テーブル）
  if (tables[0] && tables[0].records) {
    renderCorrectionRows(tables[0].records);
  }

  // 3. 各ボタンのイベントリスナー
  const approveBtn = container.querySelector("[data-testid='approve-button']");
  const rejectBtn = container.querySelector("[data-testid='reject-button']");
  const backBtn = container.querySelector("[data-testid='back-button']");
  const cancelBtn = container.querySelector("[data-testid='cancel-button']");
  const viewDuplicateBtn = container.querySelector("[data-testid='view-duplicate-btn']");
  const viewConflictBtn = container.querySelector("[data-testid='view-conflict-btn']");
  const viewHistoryBtn = container.querySelector("[data-testid='view-history-btn']");

  // 承認して登録
  if (approveBtn) {
    approveBtn.addEventListener("click", async () => {
      if (!confirm("この受注データを承認して基幹システムに登録しますか？")) return;

      // 承認フロー実行画面へ遷移
      window.showScreen("scr-1781406421345");
    });
  }

  // 却下
  if (rejectBtn) {
    rejectBtn.addEventListener("click", async () => {
      const reason = prompt("却下理由を入力してください:");
      if (!reason) return;

      // 却下処理（API呼び出し）
      const result = await window.aivicApi.update(0, "current-order-id", {
        フロー_ステータス: "却下",
        却下_理由: reason
      });

      if (result) {
        alert("受注データを却下しました");
        window.showScreen("scr-1781406322572"); // ダッシュボードへ戻る
      }
    });
  }

  // 修正に戻る
  if (backBtn) {
    backBtn.addEventListener("click", () => {
      window.showScreen("scr-1781406337850"); // 受注データ詳細確認・修正画面へ
    });
  }

  // キャンセル
  if (cancelBtn) {
    cancelBtn.addEventListener("click", () => {
      if (confirm("処理をキャンセルしますか？")) {
        window.showScreen("scr-1781406322572"); // ダッシュボードへ戻る
      }
    });
  }

  // 重複受注詳細確認
  if (viewDuplicateBtn) {
    viewDuplicateBtn.addEventListener("click", () => {
      window.showScreen("scr-1781406366334"); // 重複受注検出・比較画面へ
    });
  }

  // チャネル間矛盾詳細確認
  if (viewConflictBtn) {
    viewConflictBtn.addEventListener("click", () => {
      window.showScreen("scr-1781406379487"); // チャネル間矛盾検出画面へ
    });
  }

  // 全履歴を表示
  if (viewHistoryBtn) {
    viewHistoryBtn.addEventListener("click", () => {
      window.showScreen("scr-1781406434707"); // 受注データ修正履歴画面へ
    });
  }
}

