function(container, apiUrl, tables) {
  // テーブルインデックス
  const DUPLICATES_IDX = 0;      // 重複受注検出
  const SCORES_IDX = 1;           // 信頼度スコア
  const CONFLICTS_IDX = 2;        // チャネル間矛盾検出
  const FLOW_IDX = 3;             // 連携承認フロー

  let duplicateGroups = [];
  let selectedGroupId = null;
  let selectedMasterId = null;
  let selectedMergeId = null;
  let mergeSelections = {}; // { fieldName: "master" | "merge" }

  // ========== グループ一覧の再描画 ==========
  function renderGroupList(groups) {
    const list = container.querySelector("#group-list");
    list.innerHTML = groups.map(group => {
      const isSelected = group.id === selectedGroupId;
      return `
        <div class="group-item" data-id="${group.id}" style="padding: 10px 12px; border-bottom: 1px solid var(--border); cursor: pointer; background: ${isSelected ? 'rgba(255,165,0,0.1)' : 'transparent'}; transition: background 0.2s;">
          <div style="font-size: 11px; color: var(--text-muted); margin-bottom: 2px;">グループ #${group.id.substring(0, 8)}</div>
          <div style="font-size: 12px; font-weight: 600; color: var(--text); margin-bottom: 4px;">
            ${group.master_order_id ? group.master_order_id.substring(0, 12) : '—'}
          </div>
          <div style="font-size: 10px; color: var(--text-muted);">
            重複スコア: <strong style="color: var(--primary);">${group.duplicate_score || 0}</strong>
          </div>
          <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">
            ステータス: <span style="color: ${group.duplicate_status === '統合済み' ? '#4ade80' : '#f97316'};">${group.duplicate_status || '未確認'}</span>
          </div>
        </div>
      `;
    }).join("");

    // グループクリックイベント
    container.querySelectorAll(".group-item").forEach(el => {
      el.addEventListener("click", () => {
        selectedGroupId = el.dataset.id;
        const group = groups.find(g => g.id === selectedGroupId);
        if (group) {
          selectedMasterId = group.master_order_id;
          selectedMergeId = group.sub_order_id;
          mergeSelections = {};
          renderComparison();
          renderGroupList(groups);
        }
      });
    });
  }

  // ========== 差分比較の再描画 ==========
  function renderComparison() {
    if (!selectedMasterId || !selectedMergeId) {
      container.querySelector("#comparison-tbody").innerHTML = `
        <tr><td colspan="4" style="text-align: center; padding: 20px; color: var(--text-muted);">グループを選択してください</td></tr>
      `;
      return;
    }

    container.querySelector("#master-order-id").textContent = selectedMasterId.substring(0, 16);
    container.querySelector("#merge-order-id").textContent = selectedMergeId.substring(0, 16);

    // サンプル比較データ（実際には API から取得）
    const comparisonFields = [
      { field: "顧客名", master: "株式会社ABC", merge: "ABC株式会社", masterScore: 95, mergeScore: 92 },
      { field: "電話番号", master: "090-1234-5678", merge: "09012345678", masterScore: 88, mergeScore: 85 },
      { field: "住所", master: "東京都渋谷区1-2-3", merge: "東京都渋谷区1-2-3", masterScore: 100, mergeScore: 100 },
      { field: "受注金額", master: "¥150,000", merge: "¥150,000", masterScore: 100, mergeScore: 100 },
      { field: "商品コード", master: "PROD-001", merge: "PROD-001", masterScore: 100, mergeScore: 100 },
      { field: "配送先", master: "東京都渋谷区1-2-3", merge: "東京都渋谷区1-2-3", masterScore: 100, mergeScore: 100 },
    ];

    const tbody = container.querySelector("#comparison-tbody");
    tbody.innerHTML = comparisonFields.map(row => {
      const selected = mergeSelections[row.field] || "master";
      return `
        <tr style="border-bottom: 1px solid var(--border);">
          <td style="padding: 10px 0; color: var(--text); font-weight: 500;">${row.field}</td>
          <td style="padding: 10px 12px; color: var(--text); background: ${selected === 'master' ? 'rgba(255,165,0,0.08)' : 'transparent'};">
            ${row.master}
            <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">信頼度: ${row.masterScore}%</div>
          </td>
          <td style="padding: 10px 12px; color: var(--text); background: ${selected === 'merge' ? 'rgba(255,165,0,0.08)' : 'transparent'};">
            ${row.merge}
            <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">信頼度: ${row.mergeScore}%</div>
          </td>
          <td style="padding: 10px 0; text-align: center;">
            <div style="display: flex; gap: 4px; justify-content: center;">
              <button class="select-value-btn" data-field="${row.field}" data-value="master" style="padding: 4px 8px; font-size: 10px; background: ${selected === 'master' ? 'var(--primary)' : 'transparent'}; color: ${selected === 'master' ? '#fff' : 'var(--text)'}; border: 1px solid ${selected === 'master' ? 'var(--primary)' : 'rgba(255,255,255,0.18)'}; border-radius: 3px; cursor: pointer;">M</button>
              <button class="select-value-btn" data-field="${row.field}" data-value="merge" style="padding: 4px 8px; font-size: 10px; background: ${selected === 'merge' ? 'var(--primary)' : 'transparent'}; color: ${selected === 'merge' ? '#fff' : 'var(--text)'}; border: 1px solid ${selected === 'merge' ? 'var(--primary)' : 'rgba(255,255,255,0.18)'}; border-radius: 3px; cursor: pointer;">S</button>
            </div>
          </td>
        </tr>
      `;
    }).join("");

    // 値選択ボタンのイベント
    container.querySelectorAll(".select-value-btn").forEach(btn => {
      btn.addEventListener("click", () => {
        const field = btn.dataset.field;
        const value = btn.dataset.value;
        mergeSelections[field] = value;
        renderComparison();
        updateMergePreview();
      });
    });

    // スコア表示
    container.querySelector("#master-score").textContent = "92";
    container.querySelector("#merge-score").textContent = "88";

    // チャネル間矛盾表示
    container.querySelector("#channel-conflicts").innerHTML = `
      <div style="padding: 6px; background: rgba(249,115,22,0.1); border-left: 2px solid #f97316; border-radius: 2px; margin-bottom: 6px;">
        <div style="font-size: 10px; color: #f97316; font-weight: 500;">⚠ 電話番号形式の矛盾</div>
        <div style="font-size: 10px; color: var(--text-muted); margin-top: 2px;">Web: 090-1234-5678 vs 電話: 09012345678</div>
      </div>
    `;
  }

  // ========== 統合プレビューの更新 ==========
  function updateMergePreview() {
    const preview = container.querySelector("#merge-preview");
    const previewLines = Object.entries(mergeSelections).map(([field, source]) => {
      const value = source === 'master' ? '株式会社ABC' : 'ABC株式会社'; // サンプル
      return `<div>✓ ${field}: ${value}</div>`;
    });
    preview.innerHTML = previewLines.length > 0 ? previewLines.join("") : "<div style='color: var(--text-muted);'>値を選択してください</div>";
  }

  // ========== 初期データ読み込み ==========
  async function loadInitialData() {
    try {
      const duplicates = await window.aivicApi.list(DUPLICATES_IDX);
      if (duplicates && duplicates.length > 0) {
        duplicateGroups = duplicates;
        renderGroupList(duplicateGroups);
      }
    } catch (err) {
      console.error("Failed to load duplicates:", err);
    }
  }

  // ========== グループ検索 ==========
  container.querySelector("#group-search").addEventListener("input", (e) => {
    const keyword = e.target.value.toLowerCase();
    const filtered = duplicateGroups.filter(g => 
      (g.master_order_id || "").toLowerCase().includes(keyword) ||
      (g.sub_order_id || "").toLowerCase().includes(keyword)
    );
    renderGroupList(filtered);
  });

  // ========== マージルール変更 ==========
  container.querySelector("#merge-rule").addEventListener("change", (e) => {
    const rule = e.target.value;
    if (rule === "master-priority") {
      mergeSelections = { "顧客名": "master", "電話番号": "master", "住所": "master", "受注金額": "master", "商品コード": "master", "配送先": "master" };
    } else if (rule === "higher-score") {
      mergeSelections = { "顧客名": "master", "電話番号": "merge", "住所": "master", "受注金額": "master", "商品コード": "master", "配送先": "master" };
    } else if (rule === "recent") {
      mergeSelections = { "顧客名": "merge", "電話番号": "merge", "住所": "master", "受注金額": "master", "商品コード": "master", "配送先": "master" };
    }
    renderComparison();
    updateMergePreview();
  });

  // ========== 統合実行ボタン ==========
  container.querySelector("#btn-merge").addEventListener("click", async () => {
    if (!selectedMasterId || !selectedMergeId) {
      alert("グループを選択してください");
      return;
    }
    if (Object.keys(mergeSelections).length === 0) {
      alert("マージルールを選択してください");
      return;
    }

    const approver = container.querySelector("#approver").value;
    if (!approver) {
      alert("承認者を選択してください");
      return;
    }

    try {
      // 統合処理を実行
      const mergeResult = await window.aivicApi.save(FLOW_IDX, {
        order_data_id: selectedMasterId,
        master_order_id: selectedMasterId,
        merge_order_id: selectedMergeId,
        merge_selections: JSON.stringify(mergeSelections),
        merge_rule: container.querySelector("#merge-rule").value,
        priority_rank: container.querySelector("#priority-rank").value,
        approver_id: approver,
        flow_status: "承認待ち",
        approval_status: "未判定"
      });

      if (mergeResult) {
        alert("統合処理が完了しました。承認フローに進みます。");
        window.showScreen("scr-1781406421345"); // 連携承認フロー実行画面へ
      }
    } catch (err) {
      console.error("Merge failed:", err);
      alert("統合処理に失敗しました");
    }
  });

  // ========== キャンセルボタン ==========
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    if (confirm("処理をキャンセルしますか？")) {
      window.showScreen("scr-1781406366334"); // 重複受注検出・比較画面へ
    }
  });

  // ========== 戻るボタン ==========
  container.querySelector("#btn-back").addEventListener("click", () => {
    selectedGroupId = null;
    selectedMasterId = null;
    selectedMergeId = null;
    mergeSelections = {};
    renderGroupList(duplicateGroups);
    container.querySelector("#comparison-tbody").innerHTML = `
      <tr><td colspan="4" style="text-align: center; padding: 20px; color: var(--text-muted);">グループを選択してください</td></tr>
    `;
  });

  // ========== 初期化 ==========
  loadInitialData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0=受注データ検証結果, 1=受注データ修正履歴, 2=信頼度スコア, 3=重複受注検出, 4=チャネル間矛盾検出, 5=連携承認フロー
  const validationTableIndex = 0;
  const correctionHistoryIndex = 1;
  const trustScoreIndex = 2;
  const duplicateIndex = 3;
  const channelConflictIndex = 4;
  const approvalFlowIndex = 5;

  let currentValidationId = null;
  let currentOrderId = null;
  let allValidationResults = [];

  // ===== 1. 再描画関数 =====
  function renderValidationResults(rows) {
    const tbody = container.querySelector("#validation-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: var(--bg-main); color: var(--text-muted); text-align: center;"><td colspan="6" style="padding: 24px;">検証結果がありません</td></tr>';
      updateKPIs([]);
      return;
    }

    allValidationResults = rows;
    updateKPIs(rows);

    tbody.innerHTML = rows.map(r => {
      const statusColor = r.検証ステータス === '合格' ? '#4ade80' : r.検証ステータス === '不合格' ? '#f87171' : '#fbbf24';
      const severityColor = r.重要度 === '致命的' ? '#f87171' : r.重要度 === '高' ? '#fb923c' : r.重要度 === '中' ? '#fbbf24' : '#a3e635';

      return `
        <tr data-id="${r.検証結果ID || ''}" style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='rgba(0,0,0,0.1)'" onmouseout="this.style.background='var(--bg-main)'">
          <td style="padding: 8px 12px; color: var(--text); font-size: 12px;">${r.受注ID ? r.受注ID.substring(0, 8) : '-'}</td>
          <td style="padding: 8px 12px; color: ${statusColor}; font-weight: 600; font-size: 12px;">${r.検証ステータス || '-'}</td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 12px;">${r.エラー分類 || '-'}</td>
          <td style="padding: 8px 12px; color: ${severityColor}; font-weight: 600; font-size: 12px;">${r.重要度 || '-'}</td>
          <td style="padding: 8px 12px; color: var(--text); font-size: 12px;">${r.対応状況 || '未対応'}</td>
          <td style="padding: 8px 12px; text-align: center;">
            <button class="action-btn secondary view-detail-btn" data-id="${r.検証結果ID || ''}" style="padding: 4px 8px; font-size: 11px;">詳細</button>
          </td>
        </tr>
      `;
    }).join('');
  }

  function updateKPIs(rows) {
    const total = rows.length;
    const passed = rows.filter(r => r.検証ステータス === '合格').length;
    const failed = rows.filter(r => r.検証ステータス === '不合格').length;
    const warning = rows.filter(r => r.検証ステータス === '警告').length;

    container.querySelector('[data-testid="kpi-total-orders"]').textContent = total;
    container.querySelector('[data-testid="kpi-passed"]').textContent = passed;
    container.querySelector('[data-testid="kpi-failed"]').textContent = failed;
    container.querySelector('[data-testid="kpi-warning"]').textContent = warning;
  }

  function showDetailPanel(validationRecord) {
    currentValidationId = validationRecord.検証結果ID;
    currentOrderId = validationRecord.受注ID;

    container.querySelector("#detail-empty").style.display = 'none';
    container.querySelector("#detail-form").style.display = 'block';
    container.querySelector("#detail-order-id").textContent = `受注ID: ${currentOrderId ? currentOrderId.substring(0, 12) : '-'}`;
    container.querySelector("#detail-error-message").textContent = validationRecord.エラー詳細 || '(エラー詳細なし)';
    container.querySelector("#detail-field-name").textContent = validationRecord.対象フィールド || '-';
    container.querySelector("#detail-detected-value").textContent = validationRecord.検出値 || '-';
    container.querySelector("#detail-expected-value").textContent = validationRecord.期待値 || '-';
    container.querySelector("#detail-correction-value").value = '';
    container.querySelector("#detail-correction-reason").value = '';
  }

  function hideDetailPanel() {
    container.querySelector("#detail-empty").style.display = 'block';
    container.querySelector("#detail-form").style.display = 'none';
    currentValidationId = null;
    currentOrderId = null;
  }

  // ===== 2. 初期データ読み込み =====
  window.aivicApi.list(validationTableIndex).then(rows => {
    renderValidationResults(rows);
  });

  // ===== 3. フィルタリング =====
  function applyFilters() {
    const statusFilter = container.querySelector('[data-testid="filter-status"]').value;
    const severityFilter = container.querySelector('[data-testid="filter-severity"]').value;

    let filtered = allValidationResults;
    if (statusFilter) {
      filtered = filtered.filter(r => r.検証ステータス === statusFilter);
    }
    if (severityFilter) {
      filtered = filtered.filter(r => r.重要度 === severityFilter);
    }

    renderValidationResults(filtered);
  }

  container.querySelector('[data-testid="filter-status"]').addEventListener('change', applyFilters);
  container.querySelector('[data-testid="filter-severity"]').addEventListener('change', applyFilters);

  // ===== 4. 検証実行ボタン =====
  container.querySelector('[data-testid="btn-validate"]').addEventListener('click', async () => {
    alert('検証実行処理を開始します（実装例）');
    // 実際には検証エンジンを呼び出し、結果を取得
    window.aivicApi.list(validationTableIndex).then(rows => {
      renderValidationResults(rows);
    });
  });

  // ===== 5. CSV出力 =====
  container.querySelector('[data-testid="btn-export-csv"]').addEventListener('click', () => {
    if (!allValidationResults || allValidationResults.length === 0) {
      alert('出力するデータがありません');
      return;
    }

    const headers = ['受注ID', 'ステータス', 'エラー分類', '重要度', '対応状況', 'エラー詳細', '対象フィールド', '検出値', '期待値'];
    const rows = allValidationResults.map(r => [
      r.受注ID || '',
      r.検証ステータス || '',
      r.エラー分類 || '',
      r.重要度 || '',
      r.対応状況 || '',
      r.エラー詳細 || '',
      r.対象フィールド || '',
      r.検出値 || '',
      r.期待値 || ''
    ]);

    const csv = '\uFEFF' + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(',')
    ).join('\n');

    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `validation_results_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // ===== 6. 詳細パネル操作 =====
  container.addEventListener('click', e => {
    const viewBtn = e.target.closest('.view-detail-btn');
    if (viewBtn) {
      const validationId = viewBtn.dataset.id;
      const record = allValidationResults.find(r => r.検証結果ID === validationId);
      if (record) {
        showDetailPanel(record);
      }
    }
  });

  container.querySelector('#detail-close').addEventListener('click', hideDetailPanel);

  // ===== 7. 修正保存 =====
  container.querySelector('#detail-save-correction').addEventListener('click', async () => {
    const correctionValue = container.querySelector('#detail-correction-value').value.trim();
    const correctionReason = container.querySelector('#detail-correction-reason').value.trim();

    if (!correctionValue) {
      alert('修正値を入力してください');
      return;
    }
    if (!correctionReason) {
      alert('修正理由を入力してください');
      return;
    }

    // 修正履歴を保存
    const correctionRecord = {
      受注データID: currentOrderId,
      修正フィールド名: container.querySelector('#detail-field-name').textContent,
      修正前の値: container.querySelector('#detail-detected-value').textContent,
      修正後の値: correctionValue,
      修正理由: correctionReason,
      修正者ID: 'current-user',
      修正日時: new Date().toISOString(),
      検証結果ID: currentValidationId
    };

    const saved = await window.aivicApi.save(correctionHistoryIndex, correctionRecord);
    if (saved) {
      alert('修正を保存しました');
      // 検証結果を更新（対応状況を「対応中」に）
      await window.aivicApi.update(validationTableIndex, currentValidationId, {
        対応状況: '対応中',
        対応者: 'current-user'
      });
      window.aivicApi.list(validationTableIndex).then(rows => {
        renderValidationResults(rows);
        hideDetailPanel();
      });
    }
  });

  // ===== 8. 承認ボタン =====
  container.querySelector('#btn-approve').addEventListener('click', async () => {
    if (!currentValidationId) {
      alert('検証結果を選択してください');
      return;
    }
    alert('承認フローを実行します');
    // 承認フロー更新
    await window.aivicApi.update(validationTableIndex, currentValidationId, {
      対応状況: '対応完了'
    });
    container.querySelector('#approval-status').textContent = '承認済み';
  });

  // ===== 9. 却下ボタン =====
  container.querySelector('#btn-reject').addEventListener('click', async () => {
    if (!currentValidationId) {
      alert('検証結果を選択してください');
      return;
    }
    const reason = prompt('却下理由を入力してください:');
    if (reason) {
      alert('却下しました: ' + reason);
      await window.aivicApi.update(validationTableIndex, currentValidationId, {
        対応状況: '未対応',
        対応コメント: reason
      });
      container.querySelector('#approval-status').textContent = '却下';
    }
  });

  // ===== 10. 基幹システム連携 =====
  container.querySelector('#btn-sync-erp').addEventListener('click', async () => {
    alert('基幹システムへの連携を開始します');
    // 実装: 連携ログテーブルに記録
  });

  // ===== 11. ダッシュボード遷移 =====
  container.querySelector('#btn-view-dashboard').addEventListener('click', () => {
    window.showScreen('scr-1781406322572');
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（データ構造から推測）
  const TABLE_CORRECTIONS = 0;        // 受注データ修正履歴
  const TABLE_VALIDATIONS = 1;        // 受注データ検証結果
  const TABLE_SCORES = 2;             // 信頼度スコア
  const TABLE_DUPLICATES = 3;         // 重複受注検出
  const TABLE_CONFLICTS = 4;          // チャネル間矛盾検出
  const TABLE_OCR = 5;                // AI_OCR読込結果
  const TABLE_VOICE = 6;              // 音声ガイダンス記録

  let selectedOrderId = null;
  let allCorrections = [];
  let allValidations = [];
  let allScores = [];
  let allDuplicates = [];
  let allConflicts = [];
  let allOcr = [];
  let allVoice = [];

  // ===== 1. 初期データ読み込み =====
  async function loadAllData() {
    try {
      allCorrections = await window.aivicApi.list(TABLE_CORRECTIONS) || [];
      allValidations = await window.aivicApi.list(TABLE_VALIDATIONS) || [];
      allScores = await window.aivicApi.list(TABLE_SCORES) || [];
      allDuplicates = await window.aivicApi.list(TABLE_DUPLICATES) || [];
      allConflicts = await window.aivicApi.list(TABLE_CONFLICTS) || [];
      allOcr = await window.aivicApi.list(TABLE_OCR) || [];
