  // ===== 3. 詳細パネルの描画 =====
  function renderDetailPanel(orderId) {
    if (!orderId) return;

    // 修正内容
    const corrections = allCorrections.filter(c => c.受注データID === orderId);
    const correctionText = corrections.length > 0
      ? corrections.map(c => `${c.修正フィールド名}: ${c.修正前の値} → ${c.修正後の値}`).join("\n")
