      container.querySelector("#diff-before").textContent = "-";
      container.querySelector("#diff-after").textContent = "-";
    }

    // 信頼度スコア
    const score = allScores.find(s => s.受注データID === orderId);
    if (score) {
      container.querySelector("#score-overall").textContent = score.全体信頼度スコア || "-";
      container.querySelector("#score-customer").textContent = score.顧客情報信頼度 || "-";
      container.querySelector("#score-amount").textContent = score.金額情報信頼度 || "-";
    } else {
      container.querySelector("#score-overall").textContent = "-";
      container.querySelector("#score-customer").textContent = "-";
      container.querySelector("#score-amount").textContent = "-";
    }

    // 検証ルール適用結果
    const validations = allValidations.filter(v => v.受注ID === orderId);
    const rulesHtml = validations.length > 0
      ? validations.map(v => `<div style="padding: 6px; margin-bottom: 4px; background: rgba(0,0,0,0.1); border-radius: 3px; border-left: 2px solid ${v.検証ステータス === '合格' ? '#4ade80' : '#ef4444'};">
          <div style="font-weight: 500; color: var(--text);">${v.検証ルールID}</div>
          <div style="color: var(--text-muted); font-size: 11px; margin-top: 2px;">${v.エラー詳細 || v.検証ステータス}</div>
        </div>`).join("")
      : '<div style="color: var(--text-muted); text-align: center; padding: 8px;">検証結果なし</div>';
    container.querySelector("#validation-rules").innerHTML = rulesHtml;

    // 重複受注検出結果
    const duplicates = allDuplicates.filter(d => d.主受注ID === orderId || d.副受注ID === orderId);
    const dupText = duplicates.length > 0
      ? duplicates.map(d => `重複スコア: ${d.重複スコア}% (${d.重複検出理由})`).join("\n")
      : "重複なし";
    container.querySelector("#duplicate-detection").textContent = dupText;

    // チャネル間矛盾検出結果
    const conflicts = allConflicts.filter(c => c.受注ID === orderId);
    const conflictText = conflicts.length > 0
      ? conflicts.map(c => `${c.矛盾項目}: ${c.チャネル1値} ≠ ${c.チャネル2値}`).join("\n")
      : "矛盾なし";
    container.querySelector("#channel-conflict").textContent = conflictText;

    // AI_OCR読込結果
    const ocr = allOcr.find(o => o.order_id === orderId);
    const ocrText = ocr ? `信頼度: ${ocr.confidence_score}% (${ocr.processing_status})` : "OCR結果なし";
    container.querySelector("#ocr-result").textContent = ocrText;

    // 音声ガイダンス記録
    const voice = allVoice.find(v => v.受注ID === orderId);
    const voiceText = voice ? `${voice.ガイダンスタイプ} (${voice.応答確認状態})` : "音声記録なし";
    container.querySelector("#voice-guidance").textContent = voiceText;

    // 修正履歴タイムライン
    const timelineHtml = corrections.length > 0
      ? corrections.map(c => `
        <div style="margin-bottom: 12px; padding-bottom: 12px; border-bottom: 1px solid rgba(255,255,255,0.1);">
          <div style="font-weight: 500; color: var(--text);">${c.修正フィールド名}</div>
          <div style="color: var(--text-muted); font-size: 11px; margin-top: 2px;">${new Date(c.修正日時).toLocaleString('ja-JP')}</div>
          <div style="color: var(--text-muted); font-size: 11px; margin-top: 2px;">理由: ${c.修正理由 || '-'}</div>
        </div>
      `).join("")
      : '<div style="color: var(--text-muted); text-align: center; padding: 8px;">履歴なし</div>';
    container.querySelector("#correction-timeline").innerHTML = timelineHtml;

    // 修正者情報
    if (corrections.length > 0) {
      const first = corrections[0];
      container.querySelector("#corrector-name").textContent = first.修正者名 || first.修正者ID || "-";
      container.querySelector("#corrector-date").textContent = first.修正日時 ? new Date(first.修正日時).toLocaleString('ja-JP') : "-";
    } else {
      container.querySelector("#corrector-name").textContent = "-";
      container.querySelector("#corrector-date").textContent = "-";
    }
  }

  // ===== 4. 検索ボタン =====
  container.querySelector("#btn-search-orders").addEventListener("click", async () => {
    const keyword = container.querySelector("#search-order-id").value.trim();
    if (!keyword) {
      renderOrdersList(allCorrections);
      return;
    }
    const filtered = allCorrections.filter(c => 
      (c.受注データID || "").includes(keyword)
    );
    renderOrdersList(filtered);
  });

  // ===== 5. 再検証ボタン =====
  container.querySelector("#btn-revalidate").addEventListener("click", async () => {
    if (!selectedOrderId) {
      alert("受注を選択してください");
      return;
    }
    alert(`受注 ${selectedOrderId.substring(0, 8)} の再検証を実行しました`);
    // 実際には API 呼び出しで検証処理を実行
    window.showScreen("scr-1781406205271"); // バリデーション失敗ログ表示画面へ遷移
  });

  // ===== 6. 承認ボタン =====
  container.querySelector("#btn-approve").addEventListener("click", async () => {
    if (!selectedOrderId) {
      alert("受注を選択してください");
      return;
    }
    alert(`受注 ${selectedOrderId.substring(0, 8)} を承認しました`);
    // 実際には API 呼び出しで承認処理を実行
    window.showScreen("scr-1781406421345"); // 連携承認フロー実行画面へ遷移
  });

  // ===== 7. 却下ボタン =====
  container.querySelector("#btn-reject").addEventListener("click", async () => {
    if (!selectedOrderId) {
      alert("受注を選択してください");
      return;
    }
    const reason = prompt("却下理由を入力してください:");
    if (reason) {
      alert(`受注 ${selectedOrderId.substring(0, 8)} を却下しました`);
      // 実際には API 呼び出しで却下処理を実行
    }
