  // ===== 8. OCR詳細ボタン =====
  container.querySelector("#btn-view-ocr").addEventListener("click", () => {
    if (!selectedOrderId) {
      alert("受注を選択してください");
      return;
    }
    window.showScreen("scr-1781406353513"); // AI-OCR読込結果確認画面へ遷移
  });

  // ===== 9. 音声再生ボタン =====
  container.querySelector("#btn-play-voice").addEventListener("click", () => {
    if (!selectedOrderId) {
      alert("受注を選択してください");
      return;
    }
    alert("音声ガイダンスを再生します");
    // 実際には音声再生処理を実装
  });

  // ===== 初期化 =====
  loadAllData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 0 = 受注データ検証結果
  const tableIndex = 0;
  let allRecords = [];
  let filteredRecords = [];

  // ============ 1. グラフ描画関数 ============
  function drawChannelChart(records) {
    const canvas = container.querySelector('#chart-channel');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    // チャネル別集計
    const channelMap = {};
    records.forEach(r => {
      const ch = r.チャネル || '不明';
      channelMap[ch] = (channelMap[ch] || 0) + 1;
    });

    const labels = Object.keys(channelMap);
    const data = Object.values(channelMap);
    const colors = ['#fbbf24', '#f87171', '#60a5fa', '#34d399', '#a78bfa'];

    // 簡易棒グラフ
    const maxVal = Math.max(...data, 1);
    const barWidth = canvas.width / (labels.length + 1);
    const barHeight = canvas.height * 0.8;

    ctx.fillStyle = 'rgba(255,255,255,0.05)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    labels.forEach((label, i) => {
      const x = (i + 0.5) * barWidth;
      const h = (data[i] / maxVal) * barHeight;
      const y = canvas.height - h - 20;

      ctx.fillStyle = colors[i % colors.length];
      ctx.fillRect(x - barWidth * 0.35, y, barWidth * 0.7, h);

      ctx.fillStyle = '#d0e4ff';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(label, x, canvas.height - 5);
      ctx.fillText(data[i], x, y - 5);
    });
  }

  function drawStatusChart(records) {
    const canvas = container.querySelector('#chart-status');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    // ステータス別集計
    const statusMap = { '合格': 0, '不合格': 0, '警告': 0 };
    records.forEach(r => {
      const st = r.検証ステータス || '不明';
      if (statusMap.hasOwnProperty(st)) statusMap[st]++;
    });

    const total = Object.values(statusMap).reduce((a, b) => a + b, 1);
    const colors = ['#4ade80', '#ef4444', '#f59e0b'];
    const labels = Object.keys(statusMap);

    let startAngle = 0;
    labels.forEach((label, i) => {
      const sliceAngle = (statusMap[label] / total) * Math.PI * 2;
      const x = canvas.width / 2;
      const y = canvas.height / 2;
      const radius = Math.min(canvas.width, canvas.height) / 2 - 20;

      ctx.fillStyle = colors[i];
      ctx.beginPath();
      ctx.moveTo(x, y);
      ctx.arc(x, y, radius, startAngle, startAngle + sliceAngle);
      ctx.closePath();
      ctx.fill();

      // ラベル
      const labelAngle = startAngle + sliceAngle / 2;
      const labelX = x + Math.cos(labelAngle) * (radius * 0.7);
      const labelY = y + Math.sin(labelAngle) * (radius * 0.7);
      ctx.fillStyle = '#d0e4ff';
      ctx.font = 'bold 12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(`${label} ${statusMap[label]}`, labelX, labelY);

      startAngle += sliceAngle;
    });
  }

  function drawScoreChart(records) {
    const canvas = container.querySelector('#chart-score');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    // スコア分布（0-20, 20-40, 40-60, 60-80, 80-100）
    const bins = [0, 0, 0, 0, 0];
    records.forEach(r => {
      const score = parseInt(r.全体信頼度スコア || 0);
      if (score < 20) bins[0]++;
      else if (score < 40) bins[1]++;
      else if (score < 60) bins[2]++;
      else if (score < 80) bins[3]++;
      else bins[4]++;
    });

    const labels = ['0-20', '20-40', '40-60', '60-80', '80-100'];
    const maxVal = Math.max(...bins, 1);
    const barWidth = canvas.width / (labels.length + 1);
    const barHeight = canvas.height * 0.8;

    ctx.fillStyle = 'rgba(255,255,255,0.05)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    labels.forEach((label, i) => {
      const x = (i + 0.5) * barWidth;
      const h = (bins[i] / maxVal) * barHeight;
      const y = canvas.height - h - 20;

      ctx.fillStyle = '#fbbf24';
      ctx.fillRect(x - barWidth * 0.35, y, barWidth * 0.7, h);

      ctx.fillStyle = '#d0e4ff';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(label, x, canvas.height - 5);
      ctx.fillText(bins[i], x, y - 5);
    });
  }

  // ============ 2. エラー種別テーブル描画 ============
  function renderErrorTable(records) {
    const tbody = container.querySelector('#error-tbody');
    const errorMap = {};

    records.forEach(r => {
      const errType = r.エラー分類 || '不明';
      if (!errorMap[errType]) {
        errorMap[errType] = { count: 0, severity: r.重要度 || '中', status: r.対応状況 || '未対応' };
      }
      errorMap[errType].count++;
    });

    const rows = Object.entries(errorMap).map(([errType, info]) => `
      <tr>
        <td>${errType}</td>
        <td style="text-align: center; font-weight: 600;">${info.count}</td>
        <td>
          <span style="display: inline-block; padding: 0.25rem 0.5rem; border-radius: 0.25rem; font-size: 0.75rem; font-weight: 500;
            ${info.severity === '致命的' ? 'background: rgba(239,68,68,0.2); color: #fca5a5;' : ''}
            ${info.severity === '高' ? 'background: rgba(245,158,11,0.2); color: #fcd34d;' : ''}
            ${info.severity === '中' ? 'background: rgba(59,130,246,0.2); color: #93c5fd;' : ''}
            ${info.severity === '低' ? 'background: rgba(74,222,128,0.2); color: #86efac;' : ''}
          ">${info.severity}</span>
        </td>
        <td>${info.status}</td>
      </tr>
    `).join('');

    tbody.innerHTML = rows || '<tr><td colspan="4" style="text-align: center; padding: 1rem; color: var(--text-muted);">エラーなし</td></tr>';
  }

  // ============ 3. KPI 更新 ============
  function updateKPIs(records) {
    const total = records.length;
    const validated = records.filter(r => r.検証ステータス).length;
    const errors = records.filter(r => r.検証ステータス === '不合格').length;
    const avgScore = records.length > 0
      ? Math.round(records.reduce((sum, r) => sum + (parseInt(r.全体信頼度スコア || 0)), 0) / records.length)
      : 0;
    const duplicates = records.filter(r => r.重複フラグ === true || r.重複フラグ === 'true').length;
    const contradictions = records.filter(r => r.チャネル間矛盾フラグ === true || r.チャネル間矛盾フラグ === 'true').length;

    container.querySelector('[data-testid="kpi-total-orders"]').textContent = total;
    container.querySelector('[data-testid="kpi-validated"]').textContent = validated;
    container.querySelector('[data-testid="kpi-errors"]').textContent = errors;
    container.querySelector('[data-testid="kpi-avg-score"]').textContent = avgScore;
    container.querySelector('[data-testid="kpi-duplicates"]').textContent = duplicates;
    container.querySelector('[data-testid="kpi-contradictions"]').textContent = contradictions;
  }

  // ============ 4. 集計実行 ============
  function applyFilters() {
    const startDate = container.querySelector('[data-testid="period-start"]').value;
    const endDate = container.querySelector('[data-testid="period-end"]').value;
    const channel = container.querySelector('[data-testid="channel-filter"]').value;
    const status = container.querySelector('[data-testid="status-filter"]').value;

    filteredRecords = allRecords.filter(r => {
      let match = true;
      if (startDate && r.検証実行日時 < startDate) match = false;
      if (endDate && r.検証実行日時 > endDate) match = false;
      if (channel && r.チャネル !== channel) match = false;
      if (status && r.検証ステータス !== status) match = false;
      return match;
    });

    updateKPIs(filteredRecords);
    renderErrorTable(filteredRecords);
    drawChannelChart(filteredRecords);
    drawStatusChart(filteredRecords);
    drawScoreChart(filteredRecords);
  }

  // ============ 5. 初期化 ============
  async function init() {
    // 初期データ読み込み
    allRecords = tables[0]?.records || [];
    filteredRecords = allRecords;

    // KPI と テーブル描画
    updateKPIs(filteredRecords);
    renderErrorTable(filteredRecords);
    drawChannelChart(filteredRecords);
    drawStatusChart(filteredRecords);
    drawScoreChart(filteredRecords);
  }

  // ============ 6. イベントリスナー ============
  container.querySelector('[data-testid="filter-apply-btn"]').addEventListener('click', applyFilters);

  container.querySelector('[data-testid="filter-reset-btn"]').addEventListener('click', () => {
    container.querySelector('[data-testid="period-start"]').value = '';
    container.querySelector('[data-testid="period-end"]').value = '';
    container.querySelector('[data-testid="channel-filter"]').value = '';
    container.querySelector('[data-testid="status-filter"]').value = '';
    filteredRecords = allRecords;
    updateKPIs(filteredRecords);
    renderErrorTable(filteredRecords);
    drawChannelChart(filteredRecords);
    drawStatusChart(filteredRecords);
    drawScoreChart(filteredRecords);
  });

  container.querySelector('[data-testid="btn-dashboard"]').addEventListener('click', () => {
    window.showScreen('scr-1781406322572');
  });

  container.querySelector('[data-testid="btn-detail"]').addEventListener('click', () => {
    window.showScreen('scr-1781406337850');
  });

  container.querySelector('[data-testid="btn-errors"]').addEventListener('click', () => {
    window.showScreen('scr-1781406605271');
  });

  container.querySelector('[data-testid="btn-duplicates"]').addEventListener('click', () => {
    window.showScreen('scr-1781406366334');
  });

  container.querySelector('[data-testid="btn-contradictions"]').addEventListener('click', () => {
    window.showScreen('scr-1781406379487');
  });

  container.querySelector('[data-testid="btn-export"]').addEventListener('click', () => {
    const csv = [
      ['検証結果ID', 'エラー分類', '重要度', '対応状況', '検証ステータス', '信頼度スコア'].join(','),
      ...filteredRecords.map(r => [
        r.検証結果ID || '',
        r.エラー分類 || '',
        r.重要度 || '',
        r.対応状況 || '',
        r.検証ステータス || '',
        r.全体信頼度スコア || ''
      ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const bom = '\uFEFF';
    const blob = new Blob([bom + csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'aggregation_results.csv';
    link.click();
  });

  init();
}

function(container, apiUrl, tables) {
