      修正前の値: beforeValue,
      修正後の値: afterValue,
      修正理由: reason,
      修正者ID: 'user-001',
      修正者名: '山田太郎',
      修正日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(1, correctionRecord);
    if (saved) {
