function(container, apiUrl, tables) {
  const validationTable = tables[0] || { records: [] };
  const duplicateTable = tables[1] || { records: [] };
  const conflictTable = tables[2] || { records: [] };

  let currentTab = 'input-error';
  let selectedValidationId = null;
  let filteredRows = [];

  // 1. 再描画関数
  function renderValidationRows(rows) {
    const tbody = container.querySelector('#validation-tbody');
    tbody.innerHTML = rows.map(r => {
      const severityColor = {
        '致命的': '#ff6a00',
        '高': '#ffaa00',
        '中': '#ffcc00',
        '低': '#00aa00'
      }[r.重要度] || '#999999';

      const statusBg = {
        '未対応': 'rgba(255,100,100,0.15)',
        '対応中': 'rgba(255,200,100,0.15)',
        '対応完了': 'rgba(100,200,100,0.15)'
      }[r.対応状況] || 'rgba(150,150,150,0.15)';

      return `
        <tr data-id="${r.検証結果ID}" class="validation-row" style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.2s;">
          <td style="padding: 10px 12px; border-right: 1px solid var(--border); color: var(--text); font-family: monospace; font-size: 11px;">${r.受注ID ? r.受注ID.substring(0, 8) : '-'}</td>
          <td style="padding: 10px 12px; border-right: 1px solid var(--border); color: var(--text);">${r.エラー分類 || '-'}</td>
          <td style="padding: 10px 12px; border-right: 1px solid var(--border);">
            <span style="display: inline-block; padding: 3px 8px; background: ${severityColor}33; color: ${severityColor}; border-radius: 3px; font-size: 11px; font-weight: 500;">${r.重要度 || '-'}</span>
          </td>
          <td style="padding: 10px 12px; border-right: 1px solid var(--border);">
            <span style="display: inline-block; padding: 3px 8px; background: ${statusBg}; color: var(--text); border-radius: 3px; font-size: 11px;">${r.対応状況 || '-'}</span>
          </td>
          <td style="padding: 10px 12px; text-align: center; color: var(--text); font-weight: 600;">${r.信頼度スコア || 0}%</td>
        </tr>
      `;
    }).join('');
  }

  // 2. 初期データ描画
  filteredRows = validationTable.records || [];
  renderValidationRows(filteredRows);

  // 3. タブ切り替え
  container.querySelectorAll('.tab-btn').forEach(btn => {
    btn.addEventListener('click', () => {
      container.querySelectorAll('.tab-btn').forEach(b => {
        b.style.color = 'var(--text-muted)';
        b.style.borderBottomColor = 'transparent';
      });
      btn.style.color = 'var(--text)';
      btn.style.borderBottomColor = 'var(--primary)';

      currentTab = btn.dataset.tab;

      if (currentTab === 'input-error') {
        filteredRows = validationTable.records || [];
      } else if (currentTab === 'duplicate') {
        filteredRows = duplicateTable.records || [];
      } else if (currentTab === 'channel-conflict') {
        filteredRows = conflictTable.records || [];
      }

      renderValidationRows(filteredRows);
      selectedValidationId = null;
      clearDetailPanel();
    });
  });

  // 4. 行選択で詳細パネル表示
  container.addEventListener('click', e => {
    const row = e.target.closest('.validation-row');
    if (row) {
      selectedValidationId = row.dataset.id;
      const rowData = filteredRows.find(r => r.検証結果ID === selectedValidationId);
      if (rowData) {
        displayDetail(rowData);
      }
    }
  });

  function displayDetail(data) {
    container.querySelector('#detail-order-id').textContent = data.受注ID ? data.受注ID.substring(0, 12) : '-';
    container.querySelector('#detail-field').textContent = data.対象フィールド || '-';
    container.querySelector('#detail-detected').textContent = data.検出値 || '-';
    container.querySelector('#detail-expected').textContent = data.期待値 || '-';
    container.querySelector('#detail-error-msg').textContent = data.エラー詳細 || '-';

    const score = data.信頼度スコア || 0;
    container.querySelector('#detail-score-bar').style.width = score + '%';
    container.querySelector('#detail-score-text').textContent = score + '%';

    container.querySelector('[data-testid="correction-value"]').value = '';
    container.querySelector('[data-testid="correction-reason"]').value = '';
    container.querySelector('[data-testid="priority-rank"]').value = '';
    container.querySelector('[data-testid="approver-assign"]').value = '';
  }

  function clearDetailPanel() {
    container.querySelector('#detail-order-id').textContent = '-';
    container.querySelector('#detail-field').textContent = '-';
    container.querySelector('#detail-detected').textContent = '-';
    container.querySelector('#detail-expected').textContent = '-';
    container.querySelector('#detail-error-msg').textContent = '-';
    container.querySelector('#detail-score-bar').style.width = '0%';
    container.querySelector('#detail-score-text').textContent = '0%';
  }

  // 5. フィルタ適用
  container.querySelector('[data-testid="filter-apply-btn"]').addEventListener('click', () => {
    const severityFilter = container.querySelector('[data-testid="severity-filter"]').value;
    const statusFilter = container.querySelector('[data-testid="status-filter"]').value;

    let sourceRows = currentTab === 'input-error' ? validationTable.records : 
                     currentTab === 'duplicate' ? duplicateTable.records : 
                     conflictTable.records;

    filteredRows = (sourceRows || []).filter(r => {
      const matchSeverity = !severityFilter || r.重要度 === severityFilter;
      const matchStatus = !statusFilter || r.対応状況 === statusFilter;
      return matchSeverity && matchStatus;
    });

    renderValidationRows(filteredRows);
    selectedValidationId = null;
    clearDetailPanel();
  });

  // 6. 修正を保存
  container.querySelector('[data-testid="save-correction-btn"]').addEventListener('click', async () => {
    if (!selectedValidationId) {
      alert('修正対象を選択してください');
      return;
    }

    const correctionValue = container.querySelector('[data-testid="correction-value"]').value.trim();
    const correctionReason = container.querySelector('[data-testid="correction-reason"]').value.trim();
    const priorityRank = container.querySelector('[data-testid="priority-rank"]').value;
    const approverAssign = container.querySelector('[data-testid="approver-assign"]').value;

    if (!correctionValue || !correctionReason || !priorityRank || !approverAssign) {
      alert('すべての項目を入力してください');
      return;
    }

    const correctionData = {
      検証結果ID: selectedValidationId,
      修正フィールド名: container.querySelector('#detail-field').textContent,
      修正前の値: container.querySelector('#detail-detected').textContent,
      修正後の値: correctionValue,
      修正理由: correctionReason,
      修正者ID: 'current-user',
      修正日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(0, correctionData);
    if (saved) {
      alert('修正を保存しました');
      container.querySelector('[data-testid="correction-value"]').value = '';
      container.querySelector('[data-testid="correction-reason"]').value = '';
      container.querySelector('[data-testid="priority-rank"]').value = '';
      container.querySelector('[data-testid="approver-assign"]').value = '';
      selectedValidationId = null;
      clearDetailPanel();
    }
  });

  // 7. キャンセル
  container.querySelector('[data-testid="cancel-correction-btn"]').addEventListener('click', () => {
    container.querySelector('[data-testid="correction-value"]').value = '';
    container.querySelector('[data-testid="correction-reason"]').value = '';
    container.querySelector('[data-testid="priority-rank"]').value = '';
    container.querySelector('[data-testid="approver-assign"]').value = '';
    selectedValidationId = null;
    clearDetailPanel();
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス（受注データ検証結果を想定）
  const tableIndex = 0;

  // 信頼度スコア表示の同期
  const scoreMinInput = container.querySelector("#input-score-min");
  const scoreMaxInput = container.querySelector("#input-score-max");
  const scoreMinDisplay = container.querySelector("#score-min-display");
  const scoreMaxDisplay = container.querySelector("#score-max-display");

  scoreMinInput.addEventListener("input", () => {
    scoreMinDisplay.textContent = scoreMinInput.value;
  });
  scoreMaxInput.addEventListener("input", () => {
    scoreMaxDisplay.textContent = scoreMaxInput.value;
  });

  // テーブル再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#table-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr><td colspan="8" style="padding: 20px; text-align: center; color: var(--text-muted);">該当する受注データがありません</td></tr>';
      container.querySelector("#record-count").textContent = "件数: 0件";
      return;
    }

    tbody.innerHTML = rows.map(row => {
      // ステータスバッジの色分け
      const statusColor = {
        "未検証": "#6b7280",
        "検証中": "#3b82f6",
        "検証完了": "#10b981",
        "修正待ち": "#f59e0b",
        "修正中": "#f59e0b",
        "承認待ち": "#8b5cf6",
        "承認済み": "#10b981",
        "却下": "#ef4444"
      };
      const statusBg = statusColor[row.検証ステータス] || "#6b7280";

      // 検証結果バッジの色分け
      const validationColor = {
        "合格": "#10b981",
        "警告": "#f59e0b",
        "不合格": "#ef4444"
      };
      const validationBg = validationColor[row.検証ステータス] || "#6b7280";

      // 信頼度スコアの色分け（0-100）
      const scoreNum = parseInt(row.全体信頼度スコア || 0);
      let scoreColor = "#ef4444"; // 低
      if (scoreNum >= 80) scoreColor = "#10b981"; // 高
      else if (scoreNum >= 60) scoreColor = "#f59e0b"; // 中

      return `
        <tr data-id="${row.検証結果ID || row.id}" style="border-bottom: 1px solid var(--border); background: var(--bg-main);">
          <td style="padding: 10px 12px; color: var(--primary); cursor: pointer; text-decoration: underline;" class="order-link">${row.受注ID || "ORD-" + (Math.random() * 10000 | 0)}</td>
          <td style="padding: 10px 12px; color: var(--text);">${row.顧客名 || "顧客未設定"}</td>
          <td style="padding: 10px 12px; color: var(--text); font-size: 12px;">${row.検証実行日時 ? new Date(row.検証実行日時).toLocaleString("ja-JP") : "-"}</td>
          <td style="padding: 10px 12px; text-align: center; color: var(--text);">${row.チャネル || "-"}</td>
          <td style="padding: 10px 12px; text-align: center;">
            <span style="display: inline-block; padding: 4px 8px; border-radius: 3px; background: ${statusBg}; color: #fff; font-size: 11px; font-weight: 500;">
              ${row.検証ステータス || "未検証"}
            </span>
          </td>
          <td style="padding: 10px 12px; text-align: center;">
            <span style="display: inline-block; padding: 4px 8px; border-radius: 3px; background: ${scoreColor}; color: #fff; font-size: 11px; font-weight: 600;">
              ${row.全体信頼度スコア || 0}%
            </span>
          </td>
          <td style="padding: 10px 12px; text-align: center;">
            <span style="display: inline-block; padding: 4px 8px; border-radius: 3px; background: ${validationBg}; color: #fff; font-size: 11px; font-weight: 500;">
              ${row.検証ステータス === "合格" ? "合格" : row.検証ステータス === "不合格" ? "不合格" : "警告"}
            </span>
          </td>
          <td style="padding: 10px 12px; text-align: center; display: flex; gap: 6px; justify-content: center;">
            <button class="action-btn secondary detail-btn" data-id="${row.検証結果ID || row.id}" style="padding: 4px 10px; font-size: 11px;">詳細</button>
            <button class="action-btn secondary history-btn" data-id="${row.検証結果ID || row.id}" style="padding: 4px 10px; font-size: 11px;">履歴</button>
          </td>
        </tr>
      `;
    }).join("");

    container.querySelector("#record-count").textContent = `件数: ${rows.length}件`;
  }

  // 初期データ表示
  renderRows(tables[0]?.records || []);

  // 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const orderNumber = container.querySelector("#input-order-number").value.trim();
    const dateFrom = container.querySelector("#input-date-from").value;
    const dateTo = container.querySelector("#input-date-to").value;
    const status = container.querySelector("#select-status").value;
    const channel = container.querySelector("#select-channel").value;
    const validation = container.querySelector("#select-validation").value;
    const scoreMin = parseInt(container.querySelector("#input-score-min").value);
    const scoreMax = parseInt(container.querySelector("#input-score-max").value);

    const allRows = await window.aivicApi.list(tableIndex) || tables[0]?.records || [];

    const filtered = allRows.filter(row => {
      // 受注番号フィルタ
      if (orderNumber && !(row.受注ID || "").includes(orderNumber)) return false;

      // 日付範囲フィルタ
      if (dateFrom || dateTo) {
        const rowDate = row.検証実行日時 ? new Date(row.検証実行日時) : null;
        if (rowDate) {
          if (dateFrom && rowDate < new Date(dateFrom)) return false;
          if (dateTo) {
            const endOfDay = new Date(dateTo);
            endOfDay.setHours(23, 59, 59, 999);
            if (rowDate > endOfDay) return false;
          }
        }
      }

      // ステータスフィルタ
      if (status && row.検証ステータス !== status) return false;

      // チャネルフィルタ
      if (channel && row.チャネル !== channel) return false;

      // 検証結果フィルタ
      if (validation) {
        const resultMap = { "合格": "合格", "警告": "警告", "不合格": "不合格" };
        const rowResult = resultMap[row.検証ステータス] || "警告";
        if (rowResult !== validation) return false;
      }

      // 信頼度スコア範囲フィルタ
      const score = parseInt(row.全体信頼度スコア || 0);
      if (score < scoreMin || score > scoreMax) return false;

      return true;
    });

    renderRows(filtered);
  });

  // リセットボタン
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#input-order-number").value = "";
    container.querySelector("#input-date-from").value = "";
    container.querySelector("#input-date-to").value = "";
    container.querySelector("#select-status").value = "";
    container.querySelector("#select-channel").value = "";
    container.querySelector("#select-validation").value = "";
    container.querySelector("#input-score-min").value = "0";
    container.querySelector("#input-score-max").value = "100";
    scoreMinDisplay.textContent = "0";
    scoreMaxDisplay.textContent = "100";
    renderRows(tables[0]?.records || []);
  });

  // CSVエクスポート
  container.querySelector("#btn-export-csv").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(tableIndex) || tables[0]?.records || [];
    if (rows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["受注番号", "顧客名", "受注日時", "チャネル", "ステータス", "信頼度スコア", "検証結果"];
    const csvContent = [
      "\uFEFF" + headers.map(h => `"${h}"`).join(","),
      ...rows.map(row => [
        row.受注ID || "",
        row.顧客名 || "",
        row.検証実行日時 ? new Date(row.検証実行日時).toLocaleString("ja-JP") : "",
        row.チャネル || "",
        row.検証ステータス || "",
        row.全体信頼度スコア || "0",
        row.検証ステータス === "合格" ? "合格" : row.検証ステータス === "不合格" ? "不合格" : "警告"
      ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `受注ステータス照会_${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  });

  // 詳細ボタン / 受注番号リンク
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      window.showScreen("scr-1781406337850"); // 受注データ詳細確認・修正画面
      return;
    }

    const orderLink = e.target.closest(".order-link");
    if (orderLink) {
      window.showScreen("scr-1781406337850"); // 受注データ詳細確認・修正画面
      return;
    }

    const historyBtn = e.target.closest(".history-btn");
    if (historyBtn) {
      const id = historyBtn.dataset.id;
      window.showScreen("scr-1781406434707"); // 受注データ修正履歴画面
      return;
    }
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const DUPLICATE_TABLE = 0;  // 重複受注検出
  const VALIDATION_TABLE = 1; // 受注データ検証結果
  const TRUST_SCORE_TABLE = 2; // 信頼度スコア
  const APPROVAL_FLOW_TABLE = 3; // 連携承認フロー
  const INTEGRATION_LOG_TABLE = 4; // 基幹システム連携ログ

  let selectedDuplicateRow = null;
  let allDuplicates = [];
  let allValidations = [];
  let allTrustScores = [];
  let allApprovalFlows = [];

  // ========== 1. 重複受注一覧の再描画 ==========
  function renderDuplicates(rows) {
    const tbody = container.querySelector("#duplicate-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id || ''}" style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.2s;">
        <td style="padding: 8px; border-right: 1px solid var(--border);">${(r.主受注ID || r.primary_order_id || '').substring(0, 8)}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border);">${(r.副受注ID || r.secondary_order_id || '').substring(0, 8)}</td>
        <td style="padding: 8px; border-right: 1px solid var(--border); font-weight: 500; color: ${(r.重複スコア || r.duplicate_score || 0) >= 80 ? '#ff6a00' : 'var(--text)'};">${r.重複スコア || r.duplicate_score || 0}%</td>
        <td style="padding: 8px;">
          <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; font-size: 11px; font-weight: 500; background: ${
            (r.重複ステータス || r.duplicate_status || '') === '確認済み' ? 'rgba(76, 175, 80, 0.2); color: #4caf50;' :
            (r.重複ステータス || r.duplicate_status || '') === '統合済み' ? 'rgba(33, 150, 243, 0.2); color: #2196f3;' :
            'rgba(255, 152, 0, 0.2); color: #ff9800;'
          }">
            ${r.重複ステータス || r.duplicate_status || '未確認'}
          </span>
        </td>
      </tr>
    `).join('');

    // 行クリックで詳細表示
    tbody.querySelectorAll('tr').forEach(tr => {
      tr.addEventListener('click', () => {
        selectedDuplicateRow = rows.find(r => r.id === tr.dataset.id);
        tbody.querySelectorAll('tr').forEach(t => t.style.background = '');
        tr.style.background = 'rgba(255, 152, 0, 0.1)';
        displayErrorDetail(selectedDuplicateRow);
      });
    });
  }

  // ========== 2. エラー検証詳細の表示 ==========
  function displayErrorDetail(duplicateRow) {
    if (!duplicateRow) {
      container.querySelector("#error-detail-panel").style.display = 'none';
      container.querySelector("#error-detail-empty").style.display = 'block';
      return;
    }

    const validation = allValidations.find(v => 
      v.受注ID === duplicateRow.主受注ID || v.order_id === duplicateRow.primary_order_id
    );

    if (!validation) {
      container.querySelector("#error-detail-panel").style.display = 'none';
      container.querySelector("#error-detail-empty").style.display = 'block';
      return;
    }

    container.querySelector("#error-detail-empty").style.display = 'none';
    container.querySelector("#error-detail-panel").style.display = 'block';

    container.querySelector("#detail-validation-id").textContent = (validation.検証結果ID || validation.id || '').substring(0, 12);
    container.querySelector("#detail-error-class").textContent = validation.エラー分類 || validation.error_category || '-';
    container.querySelector("#detail-error-msg").textContent = validation.エラー詳細 || validation.error_detail || '-';
    container.querySelector("#detail-field").textContent = validation.対象フィールド || validation.target_field || '-';
    container.querySelector("#detail-detected").textContent = validation.検出値 || validation.detected_value || '-';
    container.querySelector("#detail-expected").textContent = validation.期待値 || validation.expected_value || '-';
    container.querySelector("#detail-severity").textContent = validation.重要度 || validation.severity || '-';
    container.querySelector("#detail-status").textContent = validation.対応状況 || validation.response_status || '-';

    // 信頼度スコア表示
    const trustScore = allTrustScores.find(t => 
      t.受注データID === duplicateRow.主受注ID || t.order_id === duplicateRow.primary_order_id
    );
    if (trustScore) {
      container.querySelector("#display-trust-score").textContent = trustScore.全体信頼度スコア || trustScore.overall_score || 0;
    }

    // 承認フロー表示
    const approvalFlow = allApprovalFlows.find(a => 
      a.受注データID === duplicateRow.主受注ID || a.order_id === duplicateRow.primary_order_id
    );
    if (approvalFlow) {
      container.querySelector("#flow-status").textContent = approvalFlow.フロー_ステータス || approvalFlow.flow_status || '-';
      container.querySelector("#next-approver").textContent = approvalFlow.次_承認者_ID || approvalFlow.next_approver_id || '-';
    }
  }

  // ========== 3. 初期データ読み込み ==========
  async function loadInitialData() {
    try {
      if (tables[DUPLICATE_TABLE] && tables[DUPLICATE_TABLE].records) {
        allDuplicates = tables[DUPLICATE_TABLE].records;
        renderDuplicates(allDuplicates);
      }
      if (tables[VALIDATION_TABLE] && tables[VALIDATION_TABLE].records) {
        allValidations = tables[VALIDATION_TABLE].records;
      }
      if (tables[TRUST_SCORE_TABLE] && tables[TRUST_SCORE_TABLE].records) {
        allTrustScores = tables[TRUST_SCORE_TABLE].records;
      }
      if (tables[APPROVAL_FLOW_TABLE] && tables[APPROVAL_FLOW_TABLE].records) {
        allApprovalFlows = tables[APPROVAL_FLOW_TABLE].records;
      }
    } catch (e) {
      console.error('初期データ読み込みエラー:', e);
    }
  }

  // ========== 4. 検索ボタン ==========
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const searchKeyword = container.querySelector("#input-search-order").value.toLowerCase();
    const statusFilter = container.querySelector("#select-status").value;
    const severityFilter = container.querySelector("#select-severity").value;

    let filtered = allDuplicates;

    if (searchKeyword) {
      filtered = filtered.filter(r => 
        JSON.stringify(r).toLowerCase().includes(searchKeyword)
      );
    }

    if (statusFilter) {
      filtered = filtered.filter(r => 
        (r.重複ステータス || r.duplicate_status) === statusFilter
      );
    }

    if (severityFilter) {
      const validationsForSeverity = allValidations.filter(v => 
        (v.重要度 || v.severity) === severityFilter
      );
      const orderIds = validationsForSeverity.map(v => v.受注ID || v.order_id);
      filtered = filtered.filter(r => 
        orderIds.includes(r.主受注ID || r.primary_order_id)
      );
    }

    renderDuplicates(filtered);
  });

  // ========== 5. 検証実行ボタン ==========
  container.querySelector("#btn-run-validation").addEventListener("click", async () => {
    alert("検証処理を実行します。\n（実装: 受注データ検証ダッシュボード画面へ遷移）");
    window.showScreen("scr-1781406322572");
  });

  // ========== 6. 修正保存ボタン ==========
  container.querySelector("#btn-save-correction").addEventListener("click", async () => {
    if (!selectedDuplicateRow) {
      alert("修正対象の重複受注を選択してください");
      return;
    }

    const priority = container.querySelector("#select-priority").value;
    const correction = container.querySelector("#textarea-correction").value;

    if (!priority || !correction) {
      alert("優先度と修正内容を入力してください");
      return;
    }

    try {
      const result = await window.aivicApi.save(DUPLICATE_TABLE, {
        主受注ID: selectedDuplicateRow.主受注ID || selectedDuplicateRow.primary_order_id,
        副受注ID: selectedDuplicateRow.副受注ID || selectedDuplicateRow.secondary_order_id,
        重複ステータス: "確認済み",
        修正内容: correction,
        優先度: priority,
        更新日時: new Date().toISOString()
      });

      if (result) {
        alert("修正内容を保存しました");
        container.querySelector("#textarea-correction").value = '';
        // 再読み込み
        const updated = await window.aivicApi.list(DUPLICATE_TABLE);
        if (updated) {
          allDuplicates = updated;
          renderDuplicates(allDuplicates);
        }
      }
    } catch (e) {
      console.error('修正保存エラー:', e);
    }
  });

  // ========== 7. 承認提出ボタン ==========
  container.querySelector("#btn-submit-approval").addEventListener("click", async () => {
    if (!selectedDuplicateRow) {
      alert("承認対象の重複受注を選択してください");
      return;
    }

    alert("承認フロー実行画面へ遷移します");
    window.showScreen("scr-1781406421345");
  });

  // ========== 8. CSVエクスポートボタン ==========
  container.querySelector("#btn-export-csv").addEventListener("click", async () => {
    try {
      const rows = await window.aivicApi.list(DUPLICATE_TABLE);
      if (!rows || rows.length === 0) {
        alert("エクスポート対象データがありません");
        return;
      }

      const headers = ["主受注ID", "副受注ID", "重複検出理由", "重複スコア", "重複ステータス", "検出日時"];
      const csvContent = [
        "\uFEFF" + headers.join(","),
        ...rows.map(r => [
          r.主受注ID || r.primary_order_id || '',
          r.副受注ID || r.secondary_order_id || '',
          r.重複検出理由 || r.duplicate_reason || '',
          r.重複スコア || r.duplicate_score || '',
          r.重複ステータス || r.duplicate_status || '',
          r.作成日時 || r.created_at || ''
        ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = `重複検出結果_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    } catch (e) {
      console.error('CSVエクスポートエラー:', e);
    }
  });

  // ========== 9. 初期化 ==========
  loadInitialData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const TABLE_OCR_RESULT = 0;
  const TABLE_CONFIDENCE_SCORE = 1;
  const TABLE_CORRECTION_HISTORY = 2;

  // 現在選択中のOCR結果ID
  let selectedOcrId = null;

  // ========== 1. 再描画関数 ==========
  function renderOcrList(rows) {
    const tbody = container.querySelector("#ocr-list-tbody");
    tbody.innerHTML = rows.map(r => {
      const score = r.confidence_score || 0;
      const scoreColor = score >= 81 ? '#4ade80' : score >= 51 ? '#fbbf24' : '#f87171';
      return `
        <tr style="background: var(--bg-main); border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.2s;" 
            data-id="${r.ocr_result_id || r.id}" class="ocr-row"
            onmouseover="this.style.background='rgba(255,255,255,0.08)'"
            onmouseout="this.style.background='var(--bg-main)'">
          <td style="padding: 8px; border-right: 1px solid var(--border); color: var(--text); font-size: 12px;">${r.order_id || 'N/A'}</td>
          <td style="padding: 8px; text-align: center; color: ${scoreColor}; font-weight: 600; font-size: 12px;">${score}%</td>
        </tr>
      `;
    }).join("");
  }

  // ========== 2. 初期データ描画 ==========
  const initialRows = tables[TABLE_OCR_RESULT]?.records || [];
  renderOcrList(initialRows);

  // ========== 3. 検索ボタン ==========
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const orderId = container.querySelector("#input-order-id").value.trim();
    const channel = container.querySelector("#select-channel").value;
    const confidenceRange = container.querySelector("#select-confidence-range").value;
    const dateFrom = container.querySelector("#input-date-from").value;

    let rows = await window.aivicApi.list(TABLE_OCR_RESULT) || initialRows;

    // フィルタリング
    rows = rows.filter(r => {
      if (orderId && !r.order_id?.includes(orderId)) return false;
      if (channel && r.channel !== channel) return false;
      if (confidenceRange) {
        const score = r.confidence_score || 0;
        const [min, max] = confidenceRange.split('-').map(Number);
        if (score < min || score > max) return false;
      }
      if (dateFrom && r.created_at) {
        const rowDate = new Date(r.created_at).toISOString().split('T')[0];
        if (rowDate < dateFrom) return false;
      }
      return true;
    });

    renderOcrList(rows);
  });

  // ========== 4. 行クリック（詳細表示） ==========
  container.addEventListener("click", async e => {
    const row = e.target.closest(".ocr-row");
    if (!row) return;

    selectedOcrId = row.dataset.id;
    const allRows = await window.aivicApi.list(TABLE_OCR_RESULT) || initialRows;
    const selectedData = allRows.find(r => (r.ocr_result_id || r.id) === selectedOcrId);

    if (!selectedData) return;

    // 詳細情報を更新
    const score = selectedData.confidence_score || 0;
    container.querySelector("#detail-overall-score").textContent = `${score}%`;
    container.querySelector("#detail-overall-bar").style.width = `${score}%`;

    // OCR認識テキスト表示
    const ocrText = selectedData.extracted_text || selectedData.customer_name || '[OCR認識テキスト]';
    container.querySelector("#detail-ocr-text").textContent = ocrText;

    // 修正対象項目を自動選択（低信頼度項目があれば）
    const lowConfidenceFields = [];
    if ((selectedData.customer_name_confidence || 100) < 80) lowConfidenceFields.push('customer_name');
    if ((selectedData.order_amount_confidence || 100) < 80) lowConfidenceFields.push('order_amount');
    if ((selectedData.product_info_confidence || 100) < 80) lowConfidenceFields.push('product_code');

    if (lowConfidenceFields.length > 0) {
      container.querySelector("#select-field-to-correct").value = lowConfidenceFields[0];
    }

    // 修正入力フィールドをクリア
    container.querySelector("#input-corrected-value").value = '';
    container.querySelector("#select-correction-reason").value = '';
    container.querySelector("#textarea-correction-comment").value = '';
  });

  // ========== 5. 修正を保存ボタン ==========
  container.querySelector("#btn-save-correction").addEventListener("click", async () => {
    if (!selectedOcrId) {
      alert("修正対象のOCR結果を選択してください");
      return;
    }

    const fieldName = container.querySelector("#select-field-to-correct").value;
    const correctedValue = container.querySelector("#input-corrected-value").value.trim();
    const reason = container.querySelector("#select-correction-reason").value;
    const comment = container.querySelector("#textarea-correction-comment").value.trim();

    if (!fieldName || !correctedValue || !reason) {
      alert("修正対象項目、修正後の値、修正理由を入力してください");
      return;
    }

    // 修正履歴を保存
    const correctionData = {
      order_data_id: selectedOcrId,
      correction_field_name: fieldName,
      corrected_value: correctedValue,
      correction_reason: reason,
      correction_comment: comment,
      corrected_at: new Date().toISOString(),
      corrected_by: "current_user"
    };

    const saved = await window.aivicApi.save(TABLE_CORRECTION_HISTORY, correctionData);
    if (saved) {
      alert("修正を保存しました");
      container.querySelector("#input-corrected-value").value = '';
      container.querySelector("#select-correction-reason").value = '';
      container.querySelector("#textarea-correction-comment").value = '';
    }
  });

  // ========== 6. キャンセルボタン ==========
  container.querySelector("#btn-cancel-correction").addEventListener("click", () => {
    container.querySelector("#input-corrected-value").value = '';
    container.querySelector("#select-correction-reason").value = '';
    container.querySelector("#textarea-correction-comment").value = '';
    selectedOcrId = null;
  });

  // ========== 7. 修正対象項目選択時の自動入力 ==========
  container.querySelector("#select-field-to-correct").addEventListener("change", async e => {
    const fieldName = e.target.value;
    if (!fieldName || !selectedOcrId) return;

    const allRows = await window.aivicApi.list(TABLE_OCR_RESULT) || initialRows;
    const selectedData = allRows.find(r => (r.ocr_result_id || r.id) === selectedOcrId);

    if (!selectedData) return;

    // フィールド名に応じてOCR認識テキストを表示
    let ocrValue = '';
    if (fieldName === 'customer_name') ocrValue = selectedData.customer_name || '';
    else if (fieldName === 'order_date') ocrValue = selectedData.order_date || '';
    else if (fieldName === 'order_amount') ocrValue = selectedData.order_amount || '';
    else if (fieldName === 'product_code') ocrValue = selectedData.product_info || '';

    container.querySelector("#detail-ocr-text").textContent = ocrValue || '[OCR認識テキスト]';
  });
}

function(container, apiUrl, tables) {
  const duplicateTable = tables[0] || { records: [] };
  const conflictTable = tables[1] || { records: [] };
  const historyTable = tables[2] || { records: [] };

