      </div>
      <div style="margin-top: 8px; padding: 8px; background: rgba(0,0,0,0.1); border-radius: 4px;">
        <div style="color: var(--text-muted); font-size: 10px; margin-bottom: 2px;">検出理由</div>
        <div style="color: var(--text);">${reason}</div>
      </div>
      <div style="margin-top: 6px; padding: 8px; background: rgba(0,0,0,0.1); border-radius: 4px;">
