        <div style="color: var(--text);">${method}</div>
      </div>
    `;
  }

  // ========== 3. チャネル間矛盾の表示 ==========
  function renderChannelConflicts(duplicate) {
    const conflictDiv = container.querySelector("#channel-conflicts");
    if (!duplicate) {
      conflictDiv.innerHTML = '<div style="padding: 8px; text-align: center; color: var(--text-muted);">矛盾情報なし</div>';
      return;
    }

    const conflicts = conflictTable.records.filter(c => 
      c['受注ID'] === duplicate['主受注ID'] || c['受注ID'] === duplicate['副受注ID']
    );

    if (conflicts.length === 0) {
      conflictDiv.innerHTML = '<div style="padding: 8px; text-align: center; color: var(--text-muted);">矛盾情報なし</div>';
      return;
    }

    conflictDiv.innerHTML = conflicts.map(c => `
      <div style="padding: 8px; border-left: 3px solid #ff6a00; background: rgba(255,106,0,0.1); margin-bottom: 4px; border-radius: 2px;">
        <div style="color: var(--text); font-weight: 600; font-size: 10px;">${c['矛盾項目'] || 'N/A'}</div>
        <div style="color: var(--text-muted); font-size: 9px; margin-top: 2px;">
          <span style="color: #ff6a00;">Ch1:</span> ${c['チャネル1値'] || '—'}
        </div>
        <div style="color: var(--text-muted); font-size: 9px;">
          <span style="color: #ff6a00;">Ch2:</span> ${c['チャネル2値'] || '—'}
        </div>
      </div>
    `).join("");
  }

  // ========== 4. マージプレビューの表示 ==========
  function renderMergePreview() {
    const preview = container.querySelector("#merge-preview");
    if (selectedForMerge.size === 0) {
      preview.innerHTML = '<div style="padding: 20px; text-align: center; color: var(--text-muted);">マージ対象を選択してください</div>';
      return;
    }

    const selected = Array.from(selectedForMerge).map(id => 
      allDuplicates.find(d => (d.id || d['重複受注検出ID']) === id)
    ).filter(Boolean);

    preview.innerHTML = `
      <div style="font-size: 11px;">
        <div style="margin-bottom: 8px; padding: 8px; background: rgba(0,0,0,0.1); border-radius: 4px;">
          <div style="color: var(--text-muted); font-size: 10px; margin-bottom: 4px;">マージ対象数</div>
          <div style="color: var(--text); font-weight: 600; font-size: 14px;">${selected.length} 件</div>
        </div>
        <div style="margin-bottom: 8px;">
          <div style="color: var(--text-muted); font-size: 10px; margin-bottom: 4px;">対象受注ID</div>
          ${selected.map((s, i) => `
            <div style="padding: 6px; background: rgba(0,0,0,0.1); border-radius: 3px; margin-bottom: 4px; font-family: monospace; font-size: 9px; word-break: break-all;">
              ${i + 1}. ${s['主受注ID'] || s.mainOrderId || 'N/A'}
            </div>
          `).join("")}
        </div>
        <div style="padding: 8px; background: rgba(76,175,80,0.1); border-left: 3px solid #4caf50; border-radius: 2px;">
          <div style="color: #4caf50; font-weight: 600; font-size: 10px;">✓ マージ可能</div>
          <div style="color: var(--text-muted); font-size: 9px; margin-top: 2px;">承認者割り当てと優先度を設定してください</div>
        </div>
      </div>
    `;
  }

  // ========== 5. 修正履歴の表示 ==========
  function renderModificationHistory() {
    const histDiv = container.querySelector("#modification-history");
    const history = historyTable.records || [];
    if (history.length === 0) {
      histDiv.innerHTML = '<div style="padding: 8px; text-align: center; color: var(--text-muted);">履歴なし</div>';
      return;
    }

    histDiv.innerHTML = history.slice(0, 5).map(h => `
      <div style="padding: 6px; border-bottom: 1px solid var(--border); font-size: 9px;">
        <div style="color: var(--text); font-weight: 600;">${h['修正フィールド名'] || 'N/A'}</div>
        <div style="color: var(--text-muted); margin-top: 2px;">
          <span style="color: #ff6a00;">修正者:</span> ${h['修正者名'] || h['修正者ID'] || '—'}
        </div>
        <div style="color: var(--text-muted); font-size: 8px; margin-top: 1px;">
          ${new Date(h['修正日時']).toLocaleString('ja-JP') || '—'}
        </div>
      </div>
    `).join("");
  }

  // ========== 6. 初期データ読み込み ==========
  renderDuplicateList(allDuplicates);
  renderModificationHistory();

  // ========== 7. 行クリック時の詳細表示 ==========
  container.addEventListener("click", e => {
    const row = e.target.closest("tr[data-id]");
    if (row && !e.target.closest(".merge-checkbox")) {
      const id = row.dataset.id;
      selectedDuplicate = allDuplicates.find(d => (d.id || d['重複受注検出ID']) === id);
      renderComparisonDetail(selectedDuplicate);
      renderChannelConflicts(selectedDuplicate);
    }
  });

  // ========== 8. チェックボックス処理 ==========
  container.addEventListener("change", e => {
    if (e.target.classList.contains("merge-checkbox")) {
      const id = e.target.dataset.id;
      if (e.target.checked) {
        selectedForMerge.add(id);
      } else {
        selectedForMerge.delete(id);
      }
      renderMergePreview();
    }
    if (e.target.dataset.testid === "select-all-checkbox") {
      const checkboxes = container.querySelectorAll(".merge-checkbox");
      checkboxes.forEach(cb => {
        cb.checked = e.target.checked;
        const id = cb.dataset.id;
        if (e.target.checked) {
          selectedForMerge.add(id);
        } else {
          selectedForMerge.delete(id);
        }
      });
      renderMergePreview();
    }
  });

  // ========== 9. フィルタ適用 ==========
  container.querySelector("[data-testid='filter-button']").addEventListener("click", async () => {
    const method = container.querySelector("[data-testid='detection-method-filter']").value;
    const scoreMin = parseInt(container.querySelector("[data-testid='score-min']").value) || 0;
    const scoreMax = parseInt(container.querySelector("[data-testid='score-max']").value) || 100;
    const status = container.querySelector("[data-testid='status-filter']").value;

    let filtered = allDuplicates;
    if (method) filtered = filtered.filter(d => (d['検出方法'] || d.detectionMethod) === method);
    if (status) filtered = filtered.filter(d => (d['重複ステータス'] || d.status) === status);
    filtered = filtered.filter(d => {
      const score = d['重複スコア'] || d.duplicateScore || 0;
      return score >= scoreMin && score <= scoreMax;
    });

    renderDuplicateList(filtered);
    selectedForMerge.clear();
    renderMergePreview();
  });

  // ========== 10. マージ実行 ==========
  container.querySelector("[data-testid='merge-execute-button']").addEventListener("click", async () => {
    if (selectedForMerge.size === 0) {
      alert("マージ対象を選択してください");
      return;
    }

    const priorityRank = container.querySelector("[data-testid='priority-rank-select']").value;
    const approver = container.querySelector("[data-testid='approver-select']").value;
    const notes = container.querySelector("[data-testid='merge-notes']").value;

    if (!priorityRank || !approver) {
      alert("優先度ランクと承認者を選択してください");
      return;
    }

    const mergeData = {
      duplicateIds: Array.from(selectedForMerge),
      priorityRank,
      approverId: approver,
      notes,
      mergedAt: new Date().toISOString(),
      status: "統合済み"
    };

    const saved = await window.aivicApi.save(0, mergeData);
    if (saved) {
      alert("マージ処理を実行しました");
      selectedForMerge.clear();
      container.querySelector("[data-testid='merge-notes']").value = "";
      container.querySelector("[data-testid='priority-rank-select']").value = "";
      container.querySelector("[data-testid='approver-select']").value = "";
      renderMergePreview();
      window.aivicApi.list(0).then(rows => {
        allDuplicates = rows;
        renderDuplicateList(allDuplicates);
      });
    }
  });

  // ========== 11. キャンセル ==========
  container.querySelector("[data-testid='cancel-button']").addEventListener("click", () => {
    selectedForMerge.clear();
    container.querySelector("[data-testid='merge-notes']").value = "";
    container.querySelector("[data-testid='priority-rank-select']").value = "";
    container.querySelector("[data-testid='approver-select']").value = "";
    container.querySelectorAll(".merge-checkbox").forEach(cb => cb.checked = false);
    renderMergePreview();
    renderComparisonDetail(null);
    renderChannelConflicts(null);
  });
}
